const state={datasetTab:'page',datasetSelection:null,section:'home',tab:null,navOpen:{data:true},sidebarCollapsed:false,boot:null,market:'',role:localStorage.getItem('dip-role')||'semantic_admin',conversation:null,query:null,busy:false,searchOpen:false,graphData:null,graphSelected:null,graphView:null,reportId:null};
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const fmt=n=>Number(n||0).toLocaleString();
async function api(path,opts={}){const headers={'Content-Type':'application/json','X-Roles':state.role,'X-User':'local-ui',...(opts.headers||{})};const r=await fetch('/api'+path,{...opts,headers});let d;try{d=await r.json()}catch{d={detail:await r.text()}}if(!r.ok)throw new Error(d.detail||`HTTP ${r.status}`);return d}
function toast(msg,tone=''){const e=document.createElement('div');e.className='toast '+tone;e.textContent=msg;document.body.append(e);setTimeout(()=>e.remove(),3000)}
function pill(text,tone='neutral'){return `<span class="pill ${tone}">${esc(text)}</span>`}
function btn(text,id,cls='primary',disabled=false){return `<button class="btn ${cls}" id="${id}" ${disabled?'disabled':''}>${text}</button>`}
function empty(text){return `<div class="empty">${esc(text)}</div>`}
function scoreDots(level=3){return `<span class="dots">${[1,2,3,4].map(i=>`<i class="${i<=level?'on':''}"></i>`).join('')}</span>`}
function errorView(e){return `<div class="notice error"><strong>Something went wrong</strong><span>${esc(e.message||e)}</span></div>`}
// Hierarchical sidebar navigation. Legacy section/tab IDs are deliberately unchanged.
const sections=[['home','⌂','Home'],['ask','✦','Ask Data'],['reports','▤','Reports'],['data','▦','Data'],['semantics','◇','Ontology'],['operate','▤','Operations'],['monitor','◌','Monitor'],['admin','⚙','Administration']];
const tabs={
 reports:[['dashboards','Dashboards'],['lineage','Lineage']],
 data:[['estate','Catalog Explorer'],['catalog','Datasets'],['profile','Profiling'],['contracts','Data Contracts'],['evidence','ER Diagram'],['quality','Data Quality'],['pipeline','Data Lineage'],['sources','Sources']],
 operate:[['job-center','Job Center'],['federation','Federation'],['enterprise-search','Enterprise Search'],['connector-bench','Connectors'],['readiness','Readiness']],
 semantics:[['model','Semantic Model'],['ontology','Object Studio'],['trust','Trust Engine'],['questions','SME Review'],['ontology-graph','Ontology Graph'],['plan-lab','Plan Lab'],['golden','Question Testing'],['ontology-releases','Ontology Releases'],['impact-agent','Impact + Agents'],['studio','Semantic Studio'],['graph','Knowledge Graph'],['relationships','Relationships'],['governance','Governance'],['branches','Branches']],
 monitor:[['overview','Overview'],['evaluation','Evaluation'],['queries','Query History'],['audit','Audit Log']],
 admin:[['onboarding','Onboarding'],['ai-models','AI Models'],['actions','Actions'],['tools','Agent Tools'],['settings','Settings']]
};
function defaultTab(s){return (tabs[s]||[])[0]?.[0]||null}
function saveNav(){try{localStorage.setItem('dip-sidebar-groups',JSON.stringify(state.navOpen))}catch(_){}}
function setSection(s){if(!sections.some(x=>x[0]===s))return;const same=state.section===s;state.section=s;if(!same)state.tab=defaultTab(s);if(tabs[s]){state.navOpen[s]=same?!state.navOpen[s]:true;saveNav()}render()}
function setTab(s,t){if(!(tabs[s]||[]).some(x=>x[0]===t))return;state.section=s;state.tab=t;state.navOpen[s]=true;saveNav();render()}
function routeTitle(){const section=sections.find(x=>x[0]===state.section)?.[2]||'Workspace';const detail=(tabs[state.section]||[]).find(x=>x[0]===state.tab)?.[1];return {section,detail}}
function navMenu(){let prevGroup='';return sections.map(([id,icon,label])=>{
 const group=id==='home'||id==='ask'||id==='reports'?'WORKSPACE':id==='data'?'DATA':id==='semantics'?'ONTOLOGY':id==='operate'?'MANAGE':'SYSTEM';
 let html=group!==prevGroup?`<div class="nav-caption">${group}</div>`:'';prevGroup=group;
 const children=tabs[id]||[],expanded=!!state.navOpen[id];
 html+=`<div class="nav-family"><button type="button" data-section="${id}" class="nav-parent ${state.section===id?'active':''}" ${children.length?`aria-expanded="${expanded}" aria-controls="nav-sub-${id}"`:''} title="${esc(label)}"><span class="nav-ico" aria-hidden="true">${icon}</span><span class="nav-parent-label">${esc(label)}</span>${children.length?`<span class="nav-chevron" aria-hidden="true">${expanded?'⌄':'›'}</span>`:''}</button>`;
 if(children.length)html+=`<div class="nav-sub ${expanded?'is-open':''}" id="nav-sub-${id}" ${expanded?'':'hidden'}>${children.map(([tab,name])=>`<button type="button" data-tab="${tab}" data-parent="${id}" class="nav-child ${state.section===id&&state.tab===tab?'active':''}" ${state.section===id&&state.tab===tab?'aria-current="page"':''}><span class="nav-child-dot" aria-hidden="true"></span><span>${esc(name)}</span></button>`).join('')}</div>`;
 return html+'</div>';}).join('')}
function shell(){const markets=(state.boot.markets||[]).map(m=>`<option value="${esc(m.id)}" ${m.id===state.market?'selected':''}>${esc(m.flag)} ${esc(m.name)}</option>`).join('');const marketOptions=markets||'<option value="">No workspace — connect a source</option>';const roles=['analyst','data_steward','semantic_admin','pii_access'];const page=routeTitle();return `<div class="app-shell ${state.sidebarCollapsed?'sidebar-collapsed':''}">
<aside class="rail" aria-label="Application navigation"><div class="rail-brand"><div class="brand-mini">DI</div><div class="brand-words"><strong>Data Intelligence</strong><small>Console</small></div><button type="button" id="toggleSidebar" class="sidebar-toggle" aria-label="${state.sidebarCollapsed?'Expand':'Collapse'} sidebar" title="Toggle sidebar">${state.sidebarCollapsed?'»':'«'}</button></div>
<nav class="sidebar-nav" aria-label="Main menu">${navMenu()}</nav><div class="rail-bottom"><span class="status-dot"></span><span class="nav-version">Connected · v${esc(String(state.boot.app.version).replace(/[- ]phase\d+/ig,''))}</span></div></aside>
<div class="workspace"><header class="topbar"><div class="top-left"><div class="top-breadcrumb"><span>${esc(page.section)}</span>${page.detail?`<span class="crumb-sep">›</span><strong>${esc(page.detail)}</strong>`:''}</div></div><div class="top-right"><button class="search-trigger" id="globalSearch" title="Search data, metrics, concepts">⌕ <span>Search data, metrics, concepts</span><kbd>⌘ K</kbd></button><select id="marketSelect" class="select" aria-label="Workspace">${marketOptions}</select><select id="roleSelect" class="select role" aria-label="Development role">${roles.map(r=>`<option ${r===state.role?'selected':''}>${r}</option>`).join('')}</select><div class="avatar">${state.role.slice(0,1).toUpperCase()}</div></div></header><main id="view" class="view" tabindex="-1"></main></div></div><div id="overlay"></div>`}
function bindShell(){
 $$('[data-section]').forEach(b=>b.onclick=()=>setSection(b.dataset.section));
 $$('.sidebar-nav [data-tab]').forEach(b=>b.onclick=()=>setTab(b.dataset.parent,b.dataset.tab));
 $('#toggleSidebar').onclick=()=>{state.sidebarCollapsed=!state.sidebarCollapsed;render()};
 $('#marketSelect').onchange=e=>{state.market=e.target.value;unifiedUI.turns=[];unifiedUI.release='';unifiedUI.draft='';state.query=null;state.conversation=null;state.datasetSelection=null;state.datasetTab='page';renderPage()};
 $('#roleSelect').onchange=e=>{state.role=e.target.value;localStorage.setItem('dip-role',state.role);renderPage()};
 $('#globalSearch').onclick=openSearch;
}
function keyHandler(e){if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch()}if(e.key==='Escape'&&$('#overlay'))$('#overlay').innerHTML=''}
function render(){document.getElementById('app').innerHTML=shell();bindShell();renderPage()}
async function openSearch(){const o=$('#overlay');o.innerHTML=`<div class="modal-back"><div class="search-modal"><div class="search-input"><span>⌕</span><input id="searchInput" autofocus placeholder="Search tables, metrics, concepts, graph…"><button id="searchClose">Esc</button></div><div id="searchResults" class="search-results"><div class="search-hint">Start typing to search the governed semantic layer.</div></div></div></div>`;$('#searchClose').onclick=()=>o.innerHTML='';$('.modal-back').onclick=e=>{if(e.target.classList.contains('modal-back'))o.innerHTML=''};const input=$('#searchInput');input.focus();let timer;input.oninput=()=>{clearTimeout(timer);timer=setTimeout(async()=>{if(input.value.trim().length<2){$('#searchResults').innerHTML='<div class="search-hint">Type at least two characters.</div>';return}try{const d=await api(`/search?q=${encodeURIComponent(input.value)}&market=${state.market}`);$('#searchResults').innerHTML=d.results.map(x=>`<button class="search-result" type="button" data-result-kind="${esc(x.kind)}" data-result-id="${esc(x.id)}" title="Open ${esc(x.label)}"><span class="kind">${esc(x.kind)}</span><div><strong>${esc(x.label)}</strong><small>${esc(x.description||x.id)}</small></div><b>${Math.round((x.score||0)*100)}%</b></button>`).join('')||empty('No matches.');$$('#searchResults .search-result').forEach(b=>b.onclick=()=>{o.innerHTML='';const target={table:['data','catalog'],metric:['semantics','model'],concept:['semantics','ontology'],graph:['semantics','graph']}[b.dataset.resultKind]||['data','estate'];setTab(...target)}) }catch(e){$('#searchResults').innerHTML=errorView(e)}},220)};input.onkeydown=e=>{if(e.key==='Escape')o.innerHTML=''}}
function sectionHead(title,desc,actions=''){return `<div class="page-head"><div><h2>${esc(title)}</h2><p>${esc(desc)}</p></div><div>${actions}</div></div>`}
function statCard(label,value,hint='',tone=''){return `<div class="stat-card ${tone}"><span>${esc(label)}</span><strong>${esc(value)}</strong><small>${esc(hint)}</small></div>`}
function simpleTable(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`}
async function renderPage(){const v=$('#view');v.innerHTML='<div class="loading">Loading…</div>';try{
 if(!state.market && !((state.section==='admin'&&['onboarding','settings','ai-models'].includes(state.tab))||(state.section==='data'&&['sources','estate'].includes(state.tab)))){v.innerHTML=await setupRequiredPage();bindLocal();return}
 if(state.section==='home') v.innerHTML=await homePage();
 else if(state.section==='ask') {v.innerHTML=await askPage();bindAsk()}
 else if(state.section==='reports') v.innerHTML=await reportsPage();
 else if(state.section==='data') v.innerHTML=await dataPage();
 else if(state.section==='semantics') v.innerHTML=await semanticsPage();
 else if(state.section==='operate') v.innerHTML=await phase5Page();
 else if(state.section==='monitor') v.innerHTML=await monitorPage();
 else if(state.section==='admin') v.innerHTML=await adminPage();
 bindLocal();bindPhase2();bindPhase3();bindPhase4();bindPhase5();bindGuidedOnboarding();bindBusinessBenchmarks();
}catch(e){v.innerHTML=errorView(e)}}
function bindLocal(){const q=$$('#view [data-go]');q.forEach(b=>b.onclick=()=>setSection(b.dataset.go))}
async function setupRequiredPage(){const configured=(state.boot.data_sources||[]).filter(x=>x.configured);return `<div class="setup-empty">${sectionHead('Connect your first data source','This build contains no bundled country, customer or demo semantics. The catalog, semantic workspace and GraphRAG graph are generated only from metadata after a real connection.')}<div class="card setup-card"><div class="spark">◇</div><h3>No semantic workspace yet</h3><p>${configured.length?`${configured.length} source connector(s) are configured. Create a workspace from Admin → Onboarding.`:'Configure Athena, PostgreSQL, Snowflake or Databricks in .env / secure instance configuration, then create a workspace.'}</p><div class="setup-actions"><button class="btn primary" onclick="setTab('admin','onboarding')">Open onboarding</button><button class="btn secondary" onclick="setTab('data','sources')">View sources</button></div></div></div>`}
async function homePage(){const [cap,mon]=await Promise.all([api(`/capabilities?market=${state.market}`),api('/monitor/summary')]);const s=state.boot.stats,r=s.relationships,q=mon.queries,ev=mon.quality.latest_evaluation_score;return `<div class="home-wrap">${sectionHead('Good to see you','Ask questions, explore governed data, or review semantic health.')}
<div class="ask-hero"><div><span class="eyebrow">AI ANALYTICS</span><h3>What would you like to know?</h3><p>Answers use governed metrics, trusted joins, market semantics and permission-aware retrieval.</p></div><button data-go="ask" class="hero-input"><span>Ask a question about your data…</span><b>→</b></button></div>
<div class="quick-grid">${statCard('Data assets',fmt(s.tables),`${fmt(s.columns)} columns`)}${statCard('Trusted relationships',fmt(r.trusted),`${fmt(r.needs_review)} awaiting review`)}${statCard('Query success',q.total?Math.round(100*q.success/q.total)+'%':'—',`${q.total} recent queries`)}${statCard('Evaluation',ev==null?'Not run':Math.round(ev)+'%',mon.quality.latest_suite||'benchmark status')}</div>
<div class="home-columns"><section class="card"><div class="card-head"><div><span class="eyebrow">PLATFORM COVERAGE</span><h3>7.0 capability maturity</h3></div>${pill(cap.capabilities.length+' integrated capabilities','success')}</div><div class="cap-list">${cap.capabilities.slice(0,8).map(c=>`<div><span>${esc(c.name)}</span>${scoreDots(c.level)}</div>`).join('')}</div><button data-go="semantics" class="link-btn">Open semantic model →</button></section>
<section class="card"><div class="card-head"><div><span class="eyebrow">RECENT ACTIVITY</span><h3>Query routes</h3></div>${pill(state.boot.app.mode.toUpperCase(),state.boot.app.mode==='aws'?'success':'info')}</div><div class="route-list">${Object.entries(q.routes||{}).map(([k,n])=>`<div><span>${esc(k.replaceAll('_',' '))}</span><strong>${n}</strong></div>`).join('')||empty('No query history yet.')}</div><div class="divider"></div><div class="health-row"><span>Semantic descriptions</span><strong>${Math.round(s.description_coverage)}%</strong></div><div class="health-row"><span>Security blocks</span><strong>${mon.security.blocks}</strong></div><div class="health-row"><span>Estimated query cost</span><strong>$${Number(q.estimated_cost_usd||0).toFixed(4)}</strong></div></section></div></div>`}
async function ensureConversation(){if(state.conversation)return state.conversation;state.conversation=await api('/conversations',{method:'POST',body:JSON.stringify({market:state.market,title:'Analytics session'})});return state.conversation}
// One natural-language Ask experience; complexity and planner routing are internal.
const unifiedUI={workspace:'',release:'',releases:[],turns:[],draft:'',busy:false};
async function askPage(){
 if(unifiedUI.workspace!==state.market){unifiedUI.workspace=state.market;unifiedUI.release='';unifiedUI.releases=[];unifiedUI.turns=[];unifiedUI.draft=''}
 let warning='';
 const llm=await api('/llm/status');unifiedUI.llmReady=llm.ready;
 try{const d=await api(`/phase4/releases?workspace=${encodeURIComponent(state.market)}`);unifiedUI.releases=d.releases||[];
   if(!unifiedUI.releases.some(x=>x.release_id===unifiedUI.release))unifiedUI.release=unifiedUI.releases[0]?.release_id||'';
 }catch(e){warning=e.message;unifiedUI.releases=[];unifiedUI.release=''}
 return `${sectionHead('Ask your data','One question box for counts, certified measures, and multi-table analytics. Complex SQL is planned and verified automatically.')}
 <div class="ua-layout"><section class="ua-conversation card">
 <div class="ua-head"><span class="spark">✦</span><div><strong>Governed AI analytics</strong><small>Certified semantics · approved joins · read-only queries</small></div>${pill('Evidence checked','success')}</div>
 ${!llm.ready?`<div class="notice"><strong>Connect an AI model to ask questions.</strong><p>Verify model access and save your planning and verification choices.</p><button id="ua-connect-model" class="btn primary">Connect AI model</button></div>`:''}
 ${!unifiedUI.release?`<div class="notice">${esc(warning||'No certified ontology release is available in this workspace. Certify semantic objects and promote an ontology release to enable Ask.')}
 <button type="button" class="btn secondary" id="ua-open-release">Open ontology releases</button></div>`:''}
 <div class="ua-turns" id="ua-turns">${unifiedUI.turns.length?unifiedUI.turns.map(t=>unifiedTurn(t)).join(''):
 `<div class="ua-welcome"><h2>What would you like to know?</h2><p>Ask for an order count, a sales breakdown, or a multi-table comparison. You'll see results and their trusted SQL evidence.</p><div class="ua-suggestions"><button class="ua-example" data-q="Count Orders">Count Orders</button><button class="ua-example" data-q="Total Sales by Customer Segment">Total Sales by Customer Segment</button><button class="ua-example" data-q="Total Sales by StoreName and Customer Segment">Total Sales by StoreName and Customer Segment</button></div></div>`}</div>
 <div class="ua-compose"><label for="ua-question" class="sr-only">Question about data</label><textarea id="ua-question" rows="2" maxlength="500" placeholder="Ask a question about your certified data…" ${!unifiedUI.release||!llm.ready?'disabled':''}>${esc(unifiedUI.draft)}</textarea>
 <div class="ua-compose-actions"><span>Enter to ask · Shift+Enter for newline</span><button class="btn primary" id="ua-send" ${!unifiedUI.release||!llm.ready||unifiedUI.busy?'disabled':''}>${unifiedUI.busy?'Working…':'Ask →'}</button></div></div></section>
 <aside class="ua-context card"><h3>Trusted context</h3><label for="ua-release">Ontology release</label><select id="ua-release" class="select" ${!unifiedUI.releases.length?'disabled':''}>${unifiedUI.releases.map(r=>`<option value="${esc(r.release_id)}" ${r.release_id===unifiedUI.release?'selected':''}>${esc(r.release_id)}</option>`).join('')||'<option value="">Not certified</option>'}</select>
 <div class="ua-context-note"><strong>Automatic planning</strong><p>A verified AI model plans the question. A separate semantic review checks that the full question and previous context are represented.</p></div>
 <div class="ua-context-note"><strong>Safety</strong><p>Only certified fields and independently approved joins. Business formulas, required filters and measure grain are enforced before read-only warehouse execution.</p></div>
 <div class="ua-context-note"><strong>Details</strong><p>Open “SQL and evidence” under any answer to inspect the query, lineage and approval references.</p></div></aside></div>`;
}
function uaBarChart(rows,labelKey,valueKey){
 const items=rows.slice(0,12).map(r=>({label:r[labelKey],value:Number(r[valueKey])||0}));
 const max=Math.max(1,...items.map(item=>Math.abs(item.value)));
 return `<div class="bar-viz">${items.map(item=>`<div class="bar-row"><span>${esc(item.label)}</span><div class="bar-track"><i style="width:${Math.max(2,Math.round(Math.abs(item.value)/max*100))}%"></i></div><strong>${esc(item.value.toLocaleString(undefined,{maximumFractionDigits:2}))}</strong></div>`).join('')}</div>`;
}
function unifiedTurn(turn){
 const result=turn.result;
 if(result?.status==='needs_clarification')return `<div class="ua-turn"><div class="ua-user">${esc(turn.question)}</div><div class="notice"><strong>Please clarify</strong><p>${esc(result.clarification)}</p></div></div>`;
 if(!result)return `<div class="ua-turn"><div class="ua-user">${esc(turn.question)}</div><div class="notice error">${esc(turn.error||'Unable to answer this question safely.')}</div></div>`;
 const rows=result.rows||[],cols=result.columns||[],dims=result.structured_plan?.dimensions||[];
 const table=rows.length?simpleTable(cols,rows.slice(0,100).map(row=>`<tr>${cols.map(c=>`<td>${esc(row[c]===null?'NULL':String(row[c]))}</td>`).join('')}</tr>`)):
 `<p class="muted">${result.executed?'No rows matched the certified query.':'Validated SQL preview; no data executed.'}</p>`;
 const numeric=cols.find(c=>c!==cols[0]&&rows.some(r=>r[c]!==null&&Number.isFinite(Number(r[c]))));
 const viz=result.chart_type==='bar'&&numeric?uaBarChart(rows,cols[0],numeric):'';
 return `<div class="ua-turn"><div class="ua-user">${esc(turn.question)}</div><article class="ua-answer"><div class="ua-answer-head"><span class="eyebrow">ANSWER</span>${pill(result.executed?'Executed':'SQL preview',result.executed?'success':'info')}</div><h3>${esc(result.answer)}</h3>
 <div class="ua-tags">${pill(`${result.plan.tables.length} certified table(s)`)}${pill(`${result.plan.join_evidence.length} approved join(s)`)}${pill('AI plan + semantic review')}${result.plan.execution_engine==='duckdb'?pill((result.plan.source_ids||[]).length+' selected connectors · combined query'):''}</div>
 ${viz?`<div class="ua-viz">${viz}</div>`:''}${table}<details class="ua-evidence"><summary>SQL and evidence</summary><div class="p4-sql"><code>${esc(result.plan.sql)}</code></div><pre class="json-small">${esc(JSON.stringify({evidence:result.evidence,plan:result.structured_plan,federation:result.federation,usage:result.usage,notice:result.notice},null,2))}</pre></details></article></div>`;
}
function bindAsk(){
 if($('#ua-connect-model'))$('#ua-connect-model').onclick=()=>setTab('admin','ai-models');
 const textarea=$('#ua-question'),submit=$('#ua-send'),release=$('#ua-release');
 if(release)release.onchange=e=>{unifiedUI.release=e.target.value;unifiedUI.turns=[];unifiedUI.draft='';renderPage()};
 if($('#ua-open-release'))$('#ua-open-release').onclick=()=>setTab('semantics','ontology-releases');
 if(textarea){textarea.oninput=()=>{unifiedUI.draft=textarea.value};textarea.onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();runAsk()}}}
 if(submit)submit.onclick=runAsk;
 $$('.ua-example').forEach(b=>b.onclick=()=>{if(!textarea)return;textarea.value=b.dataset.q;unifiedUI.draft=textarea.value;runAsk()});
}
async function runAsk(){
 const q=$('#ua-question')?.value.trim();if(!q||unifiedUI.busy||!unifiedUI.release||!unifiedUI.llmReady)return;
 unifiedUI.busy=true;unifiedUI.draft='';
 const previous=unifiedUI.turns.slice().reverse().find(t=>t.result?.structured_plan)?.result;
 const previous_plan=previous?.structured_plan||null;
 unifiedUI.turns.push({question:q});const slot=unifiedUI.turns[unifiedUI.turns.length-1];
 await renderPage();
 try{slot.result=await api(`/phase4/unified/ask?workspace=${encodeURIComponent(state.market)}`,{
   method:'POST',body:JSON.stringify({release_id:unifiedUI.release,question:q,execute:true,previous_plan:previous_plan||null})});
 }catch(e){slot.error=e.message;toast(e.message,'bad')}
 finally{unifiedUI.busy=false;await renderPage();$('#ua-turns')?.scrollTo({top:999999,behavior:'smooth'})}
}
function trustTrace(q){const p=q.plan||{},route=q.routing||{},res=p.resolution||{};const mode=p.governance_mode||'governed';return `<div class="context-section"><small>EXECUTION ROUTE</small><strong>${esc((route.route||'—').replaceAll('_',' '))}</strong><span>${esc(route.reason||'')}</span></div><div class="context-section"><small>SEMANTIC CONFIDENCE</small><strong>${Math.round((p.semantic_confidence||0)*100)}%</strong></div><div class="context-section"><small>GOVERNANCE</small><strong>${esc(mode.replaceAll('_',' '))}</strong></div><div class="context-section"><small>METRIC</small><strong>${esc(typeof p.metric==='object'?(p.metric?.label||p.metric?.id):p.metric||'—')}</strong></div><div class="context-section"><small>TABLES</small><span>${(p.tables||[]).map(x=>esc(x.split('.').pop())).join(', ')||'—'}</span></div><div class="context-section"><small>GRAPH EVIDENCE</small><strong>${(res.graph_retrieval?.results||[]).length} nodes</strong></div>`}
function queryResult(q){if(q.status==='needs_clarification'){return `<div class="assistant-msg"><div class="assistant-icon">✦</div><div class="answer-card"><h3>I need one clarification</h3>${(q.plan?.ambiguities||[]).map(a=>`<p>${esc(a.reason)}</p><div class="choice-row">${(a.options||[]).map(o=>`<button>${esc(o)}</button>`).join('')}</div>`).join('')}</div></div>`}const result=q.result||{},rows=result.rows||[],cols=result.columns||Object.keys(rows[0]||{}),metadataOnly=q.routing?.route==='ontology_explanation',preview=q.plan?.governance_mode==='inferred_preview';return `<div class="assistant-msg"><div class="assistant-icon">✦</div><div class="answer-card"><div class="answer-top"><div><span class="eyebrow">ANSWER</span><h3>${metadataOnly?'Dataset explained':preview?'Provisional query completed':q.status==='success'?'Query completed':'Plan ready'}</h3></div><div class="answer-actions">${pill((q.routing?.route||'governed').replaceAll('_',' '),preview?'warn':'success')}${(!metadataOnly&&!preview)?'<button id="addToReport" class="btn secondary compact">＋ Add to report</button>':''}</div></div>${result.answer_text?`<p class="answer-text">${esc(result.answer_text)}</p>`:''}${preview?'<div class="notice warn"><strong>Inferred semantic preview</strong><span>This answer uses metadata-inferred semantics. Review and certify the metric in Semantic Studio before production use or publishing reports.</span></div>':''}${rows.length?simpleTable(cols,rows.slice(0,20).map(r=>`<tr>${cols.map(c=>`<td>${esc(r[c])}</td>`).join('')}</tr>`)):(result.answer_text?'':'<p class="muted">No rows returned in this mode.</p>')}<details><summary>SQL and reasoning</summary><pre>${esc(q.sql||'No SQL generated.')}</pre></details><div class="answer-meta"><span>${result.row_count??0} rows</span><span>${result.execution_ms??0} ms</span><span>${result.bytes_scanned!=null?fmt(result.bytes_scanned)+' bytes':'scan n/a'}</span></div></div></div>`}
async function reportsPage(){return state.tab==='lineage'?reportsLineagePage():reportsDashboardPage()}
async function reportsDashboardPage(){const d=await api(`/reports?market=${state.market}`);const reports=d.reports||[];if(!state.reportId||!reports.some(r=>r.report_id===state.reportId))state.reportId=reports[0]?.report_id||null;let rendered=null;if(state.reportId){rendered=await api(`/reports/${encodeURIComponent(state.reportId)}/render`)}return `${sectionHead('Reports','Governed BI dashboards refresh through the same semantic, security and query-routing engine as Ask.',`<button id="newReport" class="btn primary">New report</button>`)}<div class="report-layout"><aside class="report-list card"><div class="report-list-head"><span class="eyebrow">REPORTS</span><strong>${reports.length}</strong></div>${reports.map(r=>`<button class="report-item ${r.report_id===state.reportId?'active':''}" data-report="${esc(r.report_id)}"><div><strong>${esc(r.title)}</strong><small>${esc(r.description||'No description')}</small></div><span>${pill(r.status||'draft',r.status==='certified'?'success':r.status==='published'?'info':'neutral')}</span></button>`).join('')||empty('No reports yet.')}</aside><section class="report-main">${rendered?reportDashboard(rendered):empty('Create a report or add an Ask result to start.')}</section></div>`}
function reportDashboard(payload){const report=payload.report||{},widgets=payload.rendered_widgets||[];return `<div class="report-head card"><div><span class="eyebrow">${esc((report.status||'draft').toUpperCase())}</span><h2>${esc(report.title)}</h2><p>${esc(report.description||'')}</p></div><div class="report-actions"><span class="muted">Refreshed ${esc((payload.refreshed_at||'').slice(0,19).replace('T',' '))}</span><button id="refreshReport" class="btn secondary">Refresh</button>${report.status==='draft'?'<button id="publishReport" class="btn secondary">Publish</button>':''}<button id="certifyReport" class="btn secondary">Certify</button><button id="reportFilters" class="btn secondary">Filters</button><button id="reportShare" class="btn secondary">Share</button><button id="reportSchedule" class="btn secondary">Schedule</button><button id="reportExport" class="btn secondary">Export</button></div></div><div class="dashboard-grid">${widgets.map(reportWidget).join('')||`<div class="card empty-dashboard"><span class="spark">▤</span><h3>No widgets yet</h3><p>Run a governed question in Ask and choose “Add to report”.</p><button data-go="ask" class="btn primary">Go to Ask</button></div>`}</div>`}
function reportWidget(item){const w=item.widget||{},q=item.query||{},viz=item.visualization||{},rows=q.result?.rows||[],cols=q.result?.columns||Object.keys(rows[0]||{});return `<article class="bi-widget card ${w.size==='small'?'small':''}" data-widget="${esc(w.widget_id)}"><div class="bi-widget-head"><div><span class="eyebrow">${esc((viz.type||'table').toUpperCase())}</span><h3>${esc(w.title||w.question)}</h3></div>${pill((q.routing?.route||'governed').replaceAll('_',' '),'success')}</div><div class="bi-viz">${renderVisualization(viz,rows,cols)}</div><div class="bi-widget-foot"><span>${esc(w.question)}</span><button class="link-btn drill-widget" data-widget="${esc(w.widget_id)}">Drill down</button><button class="link-btn alert-widget" data-widget="${esc(w.widget_id)}">Alert</button><button class="link-btn remove-widget" data-widget="${esc(w.widget_id)}">Remove</button></div></article>`}
function renderVisualization(viz,rows,cols){const type=viz.type||'table';if(type==='kpi'){const c=viz.value||cols.find(x=>rows[0]&&isFinite(Number(rows[0][x])))||cols[0],v=rows[0]?.[c];return `<div class="kpi-viz"><strong>${formatMetricValue(v,c)}</strong><span>${esc(c||'metric')}</span></div>`}if(type==='bar'||type==='donut'){const x=viz.x||cols[0],y=viz.y||cols[1],vals=rows.slice(0,viz.limit||12).map(r=>({label:r[x],value:Number(r[y])||0})),max=Math.max(1,...vals.map(v=>Math.abs(v.value)));return `<div class="bar-viz">${vals.map(v=>`<div class="bar-row"><span>${esc(v.label)}</span><div class="bar-track"><i style="width:${Math.max(2,Math.round(Math.abs(v.value)/max*100))}%"></i></div><strong>${formatMetricValue(v.value,y)}</strong></div>`).join('')}</div>`}if(type==='line'){const x=viz.x||cols[0],y=viz.y||cols[1],vals=rows.slice(0,24).map((r,i)=>({label:r[x],value:Number(r[y])||0,i}));if(!vals.length)return empty('No chart data.');const min=Math.min(...vals.map(v=>v.value)),max=Math.max(...vals.map(v=>v.value)),range=max-min||1,pts=vals.map((v,i)=>`${20+i*(560/Math.max(1,vals.length-1))},${170-((v.value-min)/range)*130}`).join(' ');return `<div class="line-viz"><svg viewBox="0 0 600 200" preserveAspectRatio="none"><line x1="20" y1="170" x2="580" y2="170" class="axis"></line><polyline points="${pts}" class="trend-line"></polyline>${vals.map((v,i)=>`<circle cx="${20+i*(560/Math.max(1,vals.length-1))}" cy="${170-((v.value-min)/range)*130}" r="4"><title>${esc(v.label)}: ${esc(v.value)}</title></circle>`).join('')}</svg><div class="line-labels"><span>${esc(vals[0]?.label||'')}</span><span>${esc(vals[vals.length-1]?.label||'')}</span></div></div>`}return simpleTable(cols,rows.slice(0,12).map(r=>`<tr>${cols.map(c=>`<td>${esc(r[c])}</td>`).join('')}</tr>`))}
function formatMetricValue(v,col=''){const n=Number(v);if(!isFinite(n))return esc(v??'—');const l=String(col).toLowerCase();if(l.includes('revenue')||l.includes('amount')||l.includes('montant')){if(Math.abs(n)>=1e6)return '€'+(n/1e6).toFixed(2)+'M';if(Math.abs(n)>=1e3)return '€'+(n/1e3).toFixed(1)+'K';return '€'+n.toLocaleString()}return n.toLocaleString()}
async function reportsLineagePage(){const d=await api(`/reports?market=${state.market}`);const reports=d.reports||[];if(!state.reportId||!reports.some(r=>r.report_id===state.reportId))state.reportId=reports[0]?.report_id||null;const lin=state.reportId?await api(`/reports/${encodeURIComponent(state.reportId)}/lineage`):null;return `${sectionHead('Report lineage','See which governed metrics, dimensions and physical tables power each dashboard.')}<div class="report-layout"><aside class="report-list card">${reports.map(r=>`<button class="report-item ${r.report_id===state.reportId?'active':''}" data-report="${esc(r.report_id)}"><div><strong>${esc(r.title)}</strong><small>${r.widget_count} widgets</small></div></button>`).join('')||empty('No reports.')}</aside><section class="card report-lineage" id="reportLineage">${lin?renderReportLineage(lin):empty('Select a report.')}</section></div>`}
function renderReportLineage(lin){return `<div class="card-head"><div><span class="eyebrow">LINEAGE</span><h3>Report → semantic → physical</h3></div>${pill((lin.nodes||[]).length+' nodes')}</div><div class="lineage-flow">${(lin.nodes||[]).map(n=>`<div class="lineage-chip ${esc(n.type||'node')}"><span>${esc(n.type||'node')}</span><strong>${esc(n.label||n.id)}</strong></div>`).join('')}</div><div class="edge-list">${(lin.edges||[]).map(e=>`<div><small>${esc(e.type)}</small><span>${esc(e.source)}</span><b>→</b><span>${esc(e.target)}</span></div>`).join('')}</div>`}
async function createReportDialog(){const o=$('#overlay');o.innerHTML=`<div class="modal-back"><div class="dialog"><div class="dialog-head"><h3>New report</h3><button id="dialogClose">×</button></div><label>Title<input id="reportTitle" value="My analysis"></label><label>Description<textarea id="reportDesc" rows="3" placeholder="What this report is for"></textarea></label><div class="dialog-actions"><button id="dialogCancel" class="btn secondary">Cancel</button><button id="dialogCreate" class="btn primary">Create report</button></div></div></div>`;const close=()=>o.innerHTML='';$('#dialogClose').onclick=close;$('#dialogCancel').onclick=close;$('#dialogCreate').onclick=async()=>{try{const r=await api('/reports',{method:'POST',body:JSON.stringify({market:state.market,title:$('#reportTitle').value,description:$('#reportDesc').value})});state.reportId=r.report_id;close();toast('Report created','good');setSection('reports')}catch(e){toast(e.message,'bad')}}}
async function addCurrentQueryToReport(){if(!state.query)return;const d=await api(`/reports?market=${state.market}`);const reports=d.reports||[];const o=$('#overlay');o.innerHTML=`<div class="modal-back"><div class="dialog"><div class="dialog-head"><h3>Add to report</h3><button id="dialogClose">×</button></div><p class="muted">The report stores the governed semantic question and refreshes it through current security policies. Result rows are not persisted.</p><label>Report<select id="reportPick">${reports.map(r=>`<option value="${esc(r.report_id)}">${esc(r.title)}</option>`).join('')}</select></label><label>Widget title<input id="widgetTitle" value="${esc(state.query.question||'Analysis')}"></label><label>Visualization<select id="widgetChart"><option value="auto">Auto</option><option value="kpi">KPI</option><option value="bar">Bar</option><option value="line">Line</option><option value="table">Table</option></select></label><div class="dialog-actions"><button id="newFromAsk" class="btn secondary">New report</button><button id="addWidget" class="btn primary" ${reports.length?'':'disabled'}>Add widget</button></div></div></div>`;const close=()=>o.innerHTML='';$('#dialogClose').onclick=close;$('#newFromAsk').onclick=()=>{close();createReportDialog()};const add=$('#addWidget');if(add)add.onclick=async()=>{try{await api(`/reports/${encodeURIComponent($('#reportPick').value)}/widgets`,{method:'POST',body:JSON.stringify({question:state.query.question,title:$('#widgetTitle').value,chart_type:$('#widgetChart').value})});state.reportId=$('#reportPick').value;close();toast('Added to report','good')}catch(e){toast(e.message,'bad')}}}

async function dataPage(){if(['profile','contracts','evidence','quality','pipeline'].includes(state.tab))return phase2Page();if(state.tab==='estate')return enterprisePage();if(state.tab==='catalog')return catalogPage();if(state.tab==='lineage')return lineagePage();return sourcesPage()}
// Dataset workbench: left application menu → object list → contextual object tabs.
// No tabs here are global destinations; every view is attached to one selected dataset.
const datasetTabs=[['page','▤','Page'],['yaml','{}','YAML'],['profile','▥','Profile'],['sample','▦','Sample'],['transformation','⧉','Transformation'],['sql','⌘','SQL'],['lineage','⌁','Lineage']];
let datasetDetailRequest=0;
async function catalogPage(){
 const workspace=state.market;
 let assets=[],scoped=false;
 try{const overview=await api(`/phase2/overview?workspace=${encodeURIComponent(workspace)}`);assets=overview.assets||[];scoped=true}catch(e){
  // Older imported workspaces may have catalog metadata but no generated asset scope.
  assets=await api(`/catalog/tables?market=${encodeURIComponent(workspace)}`);
 }
 state.datasetAssets=assets;
 const selected=assets.find(a=>a.asset_id&&a.asset_id===state.datasetSelection?.asset_id)||assets.find(a=>a.table===state.datasetSelection?.table&&a.database===state.datasetSelection?.database)||assets[0];
 if(selected)state.datasetSelection=selected;
 else state.datasetSelection=null;
 return `${sectionHead('Datasets','Select a dataset to inspect its metadata, descriptor, profile, sample, transformation, SQL and lineage.')}<div class="dataset-layout"><aside class="dataset-object-list" aria-label="Dataset objects"><div class="dataset-list-head"><strong>Objects</strong><span>${assets.length}</span></div><div class="dataset-object-filter"><input id="tableFilter" type="search" placeholder="Filter objects…" aria-label="Filter datasets"></div><div class="dataset-objects">${assets.map(a=>`<button type="button" class="table-item dataset-object ${selected&&(a.asset_id?a.asset_id===selected.asset_id:a.table===selected.table&&a.database===selected.database)?'active':''}" data-asset="${esc(a.asset_id||'')}" data-db="${esc(a.database)}" data-table="${esc(a.table)}" aria-current="${selected&&(a.asset_id?a.asset_id===selected.asset_id:a.table===selected.table&&a.database===selected.database)?'true':'false'}"><span class="obj-icon">▦</span><div><strong>${esc(a.table)}</strong><small>${a.source_id?esc(a.source_id)+' · ':''}${esc(a.database)}${a.schema?' · '+esc(a.schema):''}</small></div></button>`).join('')}</div></aside><section class="dataset-detail" id="tableDetail">${selected?await tableDetail(selected):`<div class="dataset-empty">${empty('No datasets in this workspace. Select tables in source onboarding to populate the catalog.')}<button class="btn secondary" data-open-onboarding="true">Open onboarding</button></div>`}</section></div>`;
}
function datasetTabBar(active){return `<div class="dataset-tabs" role="tablist" aria-label="Dataset detail views">${datasetTabs.map(([id,ico,label])=>`<button class="dataset-context-tab ${id===active?'active':''}" type="button" role="tab" id="dataset-tab-${id}" data-dataset-tab="${id}" aria-selected="${id===active}" tabindex="${id===active?'0':'-1'}"><span aria-hidden="true" class="dataset-tab-icon">${ico}</span>${label}</button>`).join('')}</div>`}
function datasetYaml(data){
 const scalar=v=>JSON.stringify(v===undefined||v===null?'':v);
 const f=['kind: Dataset','lifecycle: '+scalar(data.contract?.status||'unreviewed'),`name: ${scalar(data.table)}`,`database: ${scalar(data.database)}`,`source: ${scalar(data.source_id||'catalog')}`,'columns:'];
 (data.columns||[]).forEach(c=>{f.push(`  - name: ${scalar(c.name)}`,`    type: ${scalar(c.type||c.physical_type||'unknown')}`,`    role: ${scalar(c.role||c.suggested_role||'attribute')}`,`    nullable: ${c.nullable!==false}`)});
 return f.join('\n')+'\n';
}
function datasetOverview(data){return `<div class="dataset-identity"><span class="eyebrow">DATASET DESCRIPTOR</span><h2>${esc(data.table)}</h2><div class="dataset-chips">${pill('Dataset','info')}${pill(data.contract?.status||'unreviewed')}${pill((data.columns||[]).length+' columns')}</div><p>${esc(data.description||'Physical data mapped into the semantic workspace. Definitions and approval status come from current metadata and contracts.')}</p></div><h3 class="dataset-section-title">Columns</h3>${simpleTable(['Column','Type','Role','Description'],(data.columns||[]).map(c=>`<tr><td><strong><code>${esc(c.name)}</code></strong></td><td><code>${esc(c.type||c.physical_type||'unknown')}</code></td><td>${pill(c.role||c.suggested_role||'attribute')}</td><td>${esc(c.description||c.comment||'—')}</td></tr>`))}${data.contract?`<h3 class="dataset-section-title">Data contract</h3><p class="dataset-description">Owner: ${esc(data.contract.owner||'Unassigned')} · Status: ${esc(data.contract.status)} · Version: ${esc(data.contract.version)}</p>`:''}`}
function datasetNotice(message){return `<div class="dataset-quiet"><p>${esc(message)}</p></div>`}
function datasetCode(text,language){return `<pre class="dataset-code"><code class="${esc(language||'')}">${esc(text)}</code></pre>`}
async function datasetTabContents(a,meta,tab){
 const ws=encodeURIComponent(state.market),aid=encodeURIComponent(a.asset_id||'');
 if(tab==='page')return datasetOverview(meta);
 if(tab==='yaml')return `<div class="dataset-content-head"><h3>Live descriptor · YAML</h3><p>Read-only projection of current physical metadata. This is not a published contract.</p></div>${datasetCode(datasetYaml(meta),'yaml')}`;
 if(!a.asset_id)return datasetNotice('This dataset is not in a generated, scoped workspace. Generate the workspace in Onboarding to access profiling, samples, transformations and lineage.');
 if(tab==='profile'){
  const d=await api(`/phase2/profiles?workspace=${ws}&asset_id=${aid}`);const rows=(d.profiles||[]).sort((a,b)=>String(b.profiled_at||'').localeCompare(String(a.profiled_at||'')));const p=rows[0];
  if(!p)return `<div class="dataset-content-head"><h3>Profile</h3><p>No measured profile exists for this dataset yet.</p><button type="button" id="datasetRunProfile" class="btn primary">Run standard profile</button></div>`;
  return `<div class="dataset-content-head"><h3>Measured data profile</h3><p>${esc(p.tier)} · ${esc(p.profiled_at||'')} · ${esc(p.status)}</p><button type="button" id="datasetRunProfile" class="btn secondary">Refresh profile</button></div><div class="dataset-metrics"><div><span>Rows</span><strong>${p.row_count===null?'—':fmt(p.row_count)}</strong></div><div><span>Columns profiled</span><strong>${fmt(p.columns_profiled)} / ${fmt(p.columns_total)}</strong></div><div><span>Queries executed</span><strong>${fmt(p.queries_executed)}</strong></div></div>${simpleTable(['Column','Missing %','Distinct','Measured'],(p.columns||[]).map(c=>`<tr><td>${esc(c.name)}</td><td>${c.null_pct===undefined?'—':esc(c.null_pct)+'%'}</td><td>${c.distinct_count===undefined?'—':fmt(c.distinct_count)}</td><td>${pill(c.measured?'Measured':'Metadata only',c.measured?'success':'neutral')}</td></tr>`))}`;
 }
 if(tab==='sample'){
  try{const d=await api(`/phase2/assets/${aid}/sample?workspace=${ws}&limit=10`);return `<div class="dataset-content-head"><h3>Sample rows</h3><p>${esc(d.disclaimer||'Sample records are not stored by the console.')}</p></div>${(d.rows||[]).length?simpleTable(d.columns||[],d.rows.map(row=>`<tr>${d.columns.map(c=>`<td>${esc(row[c]??'—')}</td>`).join('')}</tr>`)):datasetNotice('No sample rows found.')}`}
  catch(e){return datasetNotice(e.message)}
 }
 if(tab==='transformation'){
  const d=await api(`/phase2/transformations?workspace=${ws}`);const t=(d.transformations||[]).filter(x=>(x.inputs||[]).includes(a.asset_id)||(x.outputs||[]).includes(a.asset_id));
  return `<div class="dataset-content-head"><h3>Transformation chain</h3><p>Registered upstream and downstream transformations for this dataset.</p></div>${t.length?simpleTable(['Transformation','Description','Inputs','Outputs'],t.map(x=>`<tr><td><strong>${esc(x.label||x.transformation_id||'Transformation')}</strong></td><td>${esc(x.description||'—')}</td><td>${(x.inputs||[]).length}</td><td>${(x.outputs||[]).length}</td></tr>`)):datasetNotice('No registered transformation references this dataset. No transformation is inferred from naming alone.')}`
 }
 if(tab==='sql'){
  const parts=[a.database,a.table].filter(Boolean);const safe=parts.every(x=>/^[A-Za-z_][A-Za-z0-9_]*$/.test(x));const ref=safe?parts.map(x=>'"'+x+'"').join('.'):'(requires a compatible quoted identifier)';
  return `<div class="dataset-content-head"><h3>SQL</h3><p>Read-only, generated query template. It has not been executed or validated on an external warehouse.</p></div>${datasetCode('-- Dataset: '+a.table+'\nSELECT COUNT(*) AS row_count\nFROM '+ref+';','sql')}`;
 }
 if(tab==='lineage'){
  const d=await api(`/phase2/lineage?workspace=${ws}`);const nodes=d.nodes||[],edges=(d.edges||[]).filter(x=>(x.source_id||x.source)===a.asset_id||(x.target_id||x.target)===a.asset_id);const related=new Set([a.asset_id,...edges.flatMap(x=>[x.source_id||x.source,x.target_id||x.target])]);const matched=nodes.filter(n=>related.has(n.id));
  return `<div class="dataset-content-head"><h3>Lineage</h3><p>Registered evidence-backed dependencies for this selected dataset.</p></div>${matched.length?simpleTable(['Node','Type'],matched.map(n=>`<tr><td>${esc(n.label||n.id)}</td><td>${pill(n.type||'asset')}</td></tr>`)):''}${edges.length?simpleTable(['From','Relationship','To'],edges.map(e=>`<tr><td>${esc(e.source_id||e.source)}</td><td>${esc(e.edge_type||e.type||'depends on')}</td><td>${esc(e.target_id||e.target)}</td></tr>`)):datasetNotice('No direct lineage edges have been registered for this dataset.')}`;
 }
 return datasetNotice('Unknown dataset view.');
}
async function tableDetail(t){
 const columns=t.asset_id?(await api(`/phase2/assets/${encodeURIComponent(t.asset_id)}/metadata?workspace=${encodeURIComponent(state.market)}`)).columns||[]:await api(`/catalog/columns?database=${encodeURIComponent(t.database)}&table=${encodeURIComponent(t.table)}&market=${encodeURIComponent(state.market)}`);
 let contract=null;
 if(t.asset_id){try{const d=await api(`/phase2/contracts?workspace=${encodeURIComponent(state.market)}&asset_id=${encodeURIComponent(t.asset_id)}`);contract=d.contracts?.[0]||null}catch(_){}}
 const roles=new Map((contract?.columns||[]).map(c=>[c.name,c]));const meta={...t,columns:columns.map(c=>({...c,...(roles.get(c.name)||{})})),contract};
 const tab=datasetTabs.some(x=>x[0]===state.datasetTab)?state.datasetTab:'page';
 return `<div class="dataset-detail-header">${datasetTabBar(tab)}<div class="dataset-path">Data <span>›</span> Datasets <span>›</span> <strong>${esc(t.table)}</strong> <span>›</span> ${esc(datasetTabs.find(x=>x[0]===tab)?.[2])}</div><div class="dataset-chain">SOURCE ${esc(t.source_id||'catalog')} <span>→</span> DATASET <strong>${esc(t.table)}</strong> <span>→</span> SEMANTICS</div></div><div class="dataset-panel" role="tabpanel" aria-labelledby="dataset-tab-${tab}" id="datasetTabPanel">${await datasetTabContents(t,meta,tab)}</div>`;
}
async function datasetUpdateDetail(){
 const target=$('#tableDetail'),t=state.datasetSelection;if(!target||!t)return;const req=++datasetDetailRequest;
 target.innerHTML='<div class="loading">Loading dataset view…</div>';
 try{const html=await tableDetail(t);if(req===datasetDetailRequest&&$('#tableDetail')){$('#tableDetail').innerHTML=html;bindDatasetTabs()}}
 catch(e){if(req===datasetDetailRequest&&$('#tableDetail'))$('#tableDetail').innerHTML=errorView(e)}
}
function bindDatasetTabs(){
 $$('#tableDetail [data-dataset-tab]').forEach(b=>{b.onclick=()=>{state.datasetTab=b.dataset.datasetTab;datasetUpdateDetail()};b.onkeydown=e=>{if(!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();const idx=datasetTabs.findIndex(t=>t[0]===b.dataset.datasetTab),next=datasetTabs[(idx+(e.key==='ArrowRight'?1:-1)+datasetTabs.length)%datasetTabs.length][0];state.datasetTab=next;datasetUpdateDetail().then(()=>$('#dataset-tab-'+next)?.focus())}});
 const run=$('#datasetRunProfile');if(run)run.onclick=async()=>{run.disabled=true;run.textContent='Profiling…';try{await api(`/phase2/profiles?workspace=${encodeURIComponent(state.market)}`,{method:'POST',body:JSON.stringify({asset_id:state.datasetSelection.asset_id,tier:'standard'})});toast('Profile created','good');datasetUpdateDetail()}catch(e){toast(e.message,'bad');run.disabled=false;run.textContent='Retry profile'}};
 const ob=$('[data-open-onboarding]');if(ob)ob.onclick=()=>setTab('admin','onboarding');
}
async function datasetBindList(){
 const tf=$('#tableFilter');if(!tf)return;
 tf.oninput=()=>$$('.dataset-object').forEach(b=>{b.hidden=!b.textContent.toLowerCase().includes(tf.value.toLowerCase())});
 $$('.dataset-object').forEach(b=>b.onclick=()=>{state.datasetSelection=(state.datasetAssets||[]).find(a=>b.dataset.asset?a.asset_id===b.dataset.asset:a.table===b.dataset.table&&a.database===b.dataset.db);$$('.dataset-object').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-current',x===b?'true':'false')});state.datasetTab='page';datasetUpdateDetail()});
 bindDatasetTabs();
}
async function lineagePage(){const g=await api(`/lineage?market=${state.market}`);const nodes=(g.nodes||[]).slice(0,80),edges=(g.edges||[]).slice(0,100);return `${sectionHead('Lineage','Trace physical sources through semantic objects, metrics and query usage.')}<div class="split"><section class="card"><div class="card-head"><h3>Lineage objects</h3>${pill((g.nodes||[]).length+' nodes')}</div>${simpleTable(['Type','Object','Status'],nodes.map(n=>`<tr><td>${pill(n.type||'node','info')}</td><td><strong>${esc(n.label||n.id)}</strong><small class="sub">${esc(n.id)}</small></td><td>${esc(n.status||'—')}</td></tr>`))}</section><section class="card"><div class="card-head"><h3>Relationships</h3>${pill((g.edges||[]).length+' edges')}</div><div class="edge-list">${edges.slice(0,35).map(e=>`<div><small>${esc(e.type||e.edge_type||'LINK')}</small><span>${esc(e.source||e.from)}</span><b>→</b><span>${esc(e.target||e.to)}</span></div>`).join('')}</div></section></div>`}
async function sourcesPage(){const d=await api('/data-sources');return `${sectionHead('Data sources','One semantic control plane across supported warehouses.')}<div class="source-grid">${d.data_sources.map(s=>`<div class="source-card"><div class="source-logo">${s.id.slice(0,2).toUpperCase()}</div><div><h3>${esc(s.label)}</h3><p>${esc(s.dialect)} · ${esc(s.mode)}</p></div>${pill(s.configured?'Configured':'Not configured',s.configured?'success':'neutral')}</div>`).join('')}</div>`}
async function semanticsPage(){if(['ontology','studio','trust','questions','ontology-graph'].includes(state.tab))return phase3Page();if(['governed-ask','plan-lab','golden','ontology-releases','impact-agent'].includes(state.tab))return phase4Page();if(state.tab==='model')return modelPage();if(state.tab==='studio')return semanticStudioPage();if(state.tab==='graph')return graphPage();if(state.tab==='relationships')return relationshipPage();if(state.tab==='governance')return governancePage();return branchPage()}
async function modelPage(){const [schema,metrics,funcs]=await Promise.all([api(`/logical-schema?market=${state.market}`),api(`/metrics?market=${state.market}`),api(`/semantic/functions?market=${state.market}`)]);return `${sectionHead('Semantic model','Business objects map to governed physical data.')}<div class="summary-strip"><div><span>Entities</span><strong>${(schema.entities||[]).length}</strong></div><div><span>Dimensions</span><strong>${(schema.dimensions||[]).length}</strong></div><div><span>Metrics</span><strong>${metrics.metrics.length}</strong></div><div><span>Certified metrics</span><strong>${metrics.validation.certified_count}</strong></div></div><div class="split"><section class="card"><div class="card-head"><h3>Metrics</h3>${pill(metrics.validation.ok?'Valid':'Needs attention',metrics.validation.ok?'success':'warn')}</div>${simpleTable(['Metric','Aggregation','Additivity','Status'],metrics.metrics.map(m=>`<tr><td><strong>${esc(m.label)}</strong><small class="sub">${esc(m.description)}</small></td><td>${esc(m.aggregation)}</td><td>${esc(m.additivity)}</td><td>${pill(m.status,m.certified?'success':'neutral')}</td></tr>`))}</section><section class="card"><div class="card-head"><h3>Dimensions & entities</h3></div>${simpleTable(['Type','Name','Physical binding'],[...(schema.entities||[]).map(x=>`<tr><td>${pill('entity','info')}</td><td><strong>${esc(x.label||x.id)}</strong></td><td>${esc(x.physical?.table||'semantic')}</td></tr>`),...(schema.dimensions||[]).map(x=>`<tr><td>${pill('dimension','neutral')}</td><td><strong>${esc(x.label||x.id)}</strong></td><td>${esc(x.physical?.column||'semantic')}</td></tr>`)])}<div class="semantic-functions"><span class="eyebrow">CERTIFIED FUNCTIONS</span>${Object.entries(funcs.semantic_functions||{}).map(([k,v])=>`<div><strong>${esc(k)}</strong><small>${esc(v.description||'')}</small></div>`).join('')}</div></section></div>`}
async function semanticStudioPage(){const d=await api(`/semantic-studio?workspace=${state.market}`);const kinds=['entity','dimension','metric','concept','business_term','verified_query'];const active=state.studioKind||'metric';state.studioKind=active;const o=await api(`/semantic-studio/objects?workspace=${state.market}&kind=${active}`);return `${sectionHead('Semantic Studio','Review, edit, validate, certify and publish business semantics generated from source metadata.',`<button id="studioPublish" class="btn primary">Publish workspace</button>`)}<div class="summary-strip"><div><span>Entities</span><strong>${d.counts.entities||0}</strong></div><div><span>Dimensions</span><strong>${d.counts.dimensions||0}</strong></div><div><span>Metrics</span><strong>${d.counts.metrics||0}</strong></div><div><span>Schema drift</span><strong>${(d.schema_drift||[]).length}</strong></div></div><div class="studio-tabs">${kinds.map(k=>`<button class="studio-kind btn ${k===active?'primary':'secondary'} compact" data-kind="${k}">${k.replaceAll('_',' ')}</button>`).join('')}</div><div class="split"><section class="card"><div class="card-head"><h3>${active.replaceAll('_',' ')}</h3><button id="studioNew" class="btn primary compact">New</button></div>${simpleTable(['Name','Status','Binding','Actions'],(o.objects||[]).map(x=>`<tr><td><strong>${esc(x.label||x.preferred||x.id)}</strong><small class="sub">${esc(x.description||x.definition||x.id)}</small></td><td>${pill(x.status||'draft',x.status==='certified'?'success':'neutral')}</td><td>${esc([x.database,x.table,x.column].filter(Boolean).join('.')||'semantic')}</td><td><button class="link-btn studio-edit" data-id="${esc(x.id)}" data-kind="${active}">Edit</button> <button class="link-btn studio-review" data-id="${esc(x.id)}" data-kind="${active}">Review</button> <button class="link-btn studio-certify" data-id="${esc(x.id)}" data-kind="${active}">Certify</button> <button class="link-btn studio-deprecate" data-id="${esc(x.id)}" data-kind="${active}">Deprecate</button></td></tr>`))}</section><section class="card"><div class="card-head"><h3>Review queue</h3><span class="muted">Generated candidates</span></div>${simpleTable(['Suggestion','Status','Action'],(d.suggestions||[]).slice(0,80).map(x=>`<tr><td><strong>${esc(x.label||x.id)}</strong><small class="sub">${esc(x.reason||x.type)}</small></td><td>${pill(x.status||'inferred')}</td><td>${x.type==='metric_candidate'&&x.status!=='approved'?`<button class="link-btn studio-promote" data-id="${esc(x.id)}">Promote</button>`:'—'}</td></tr>`))}<div class="divider"></div><h3>Schema drift</h3>${(d.schema_drift||[]).length?simpleTable(['Change','Asset','Severity'],d.schema_drift.map(x=>`<tr><td>${esc(x.type)}</td><td>${esc(x.asset)}</td><td>${pill(x.severity||'info',x.severity==='high'?'warn':'neutral')}</td></tr>`)):empty('No unresolved schema drift.')}</section></div>`}
async function graphPage(){const [stats,explorer]=await Promise.all([api(`/graphrag/stats?market=${state.market}`),api(`/graphrag/explorer?market=${state.market}&depth=2&limit=300`)]);state.graphData=explorer;state.graphSelected=null;return `${sectionHead('Graph intelligence','Obsidian-style force graph for your generated semantic model. Drag nodes, pan/zoom, hover connections, search, and double-click to focus a neighborhood.',`<button id="rebuildGraph" class="btn secondary">Rebuild graph</button>`)}<div class="graph-search"><input id="graphQ" placeholder="Search GraphRAG, e.g. customer status or order date"><button id="graphRun" class="btn primary">Search</button></div><div class="graph-filterbar"><select id="graphTypeFilter" class="select"><option value="">All node types</option>${(explorer.filters?.node_types||[]).map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('')}</select><select id="graphStatusFilter" class="select"><option value="">All statuses</option>${(explorer.filters?.statuses||[]).map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('')}</select><select id="graphClusterFilter" class="select"><option value="">All clusters</option>${(explorer.clusters||[]).slice(0,80).map(x=>`<option value="${esc(x.id)}">${esc(x.id)} (${x.count})</option>`).join('')}</select><label class="check"><input id="graphTrustedOnly" type="checkbox"> Trusted edges only</label><select id="graphAuthority" class="select"><option value="0">Any authority</option><option value="0.5">Authority ≥ 50%</option><option value="0.8">Authority ≥ 80%</option></select><button id="graphApplyFilters" class="btn secondary compact">Apply</button><span class="muted">${fmt(explorer.returned_nodes||explorer.nodes?.length)} of ${fmt(explorer.total_graph_nodes||explorer.nodes?.length)} nodes</span></div><div class="summary-strip"><div><span>Graph version</span><strong>${esc(stats.version)}</strong></div><div><span>Nodes</span><strong>${fmt(stats.stats?.total_nodes||stats.stats?.nodes)}</strong></div><div><span>Edges</span><strong>${fmt(stats.stats?.total_edges||stats.stats?.edges)}</strong></div><div><span>Trusted joins</span><strong>${fmt(stats.stats?.trusted_join_edges)}</strong></div></div><div class="graph-explorer"><section class="graph-stage card"><div class="graph-toolbar"><div><button id="graphZoomOut" class="icon-btn">−</button><button id="graphZoomIn" class="icon-btn">+</button><button id="graphReset" class="icon-btn wide">Reset</button></div><span id="graphMode">Force-directed semantic graph</span></div><div id="graphCanvas" class="graph-canvas"></div></section><aside id="graphInspector" class="graph-inspector card"><div class="graph-inspector-empty"><span class="spark">◇</span><h3>Select a node</h3><p>Inspect description, authority, freshness, certification, bindings and connected relationships.</p></div></aside></div><div id="graphResults" class="card graph-ranked"><div class="card-head"><h3>Search results</h3><span class="muted">GraphRAG ranking</span></div>${empty('Search to see ranked knowledge and focus the visual graph.')}</div>`}
