async function monitorOverview(){const [m,cap]=await Promise.all([api('/monitor/summary'),api(`/capabilities?market=${state.market}`)]);return `${sectionHead('Monitor','Quality, usage, security and cost in one place.')}<div class="quick-grid">${statCard('Queries',m.queries.total,`${m.queries.success} successful`)}${statCard('P95 latency',m.queries.p95_execution_ms==null?'—':m.queries.p95_execution_ms+' ms','recent executed queries')}${statCard('Security blocks',m.security.blocks,`${Math.round((m.security.block_rate||0)*100)}% of recent queries`)}${statCard('Estimated cost','$'+Number(m.queries.estimated_cost_usd||0).toFixed(4),'recent history')}</div><div class="split"><section class="card"><div class="card-head"><h3>Execution routes</h3></div><div class="route-list">${Object.entries(m.queries.routes||{}).map(([k,n])=>`<div><span>${esc(k.replaceAll('_',' '))}</span><strong>${n}</strong></div>`).join('')||empty('No data.')}</div><div class="fineprint">p50 ${m.queries.p50_execution_ms??'—'} ms · p95 ${m.queries.p95_execution_ms??'—'} ms · p99 ${m.queries.p99_execution_ms??'—'} ms</div></section><section class="card"><div class="card-head"><h3>Capability coverage</h3>${pill('4/5 product-ready','success')}</div><div class="cap-list">${cap.capabilities.map(c=>`<div title="${esc(c.evidence)}"><span>${esc(c.name)}</span>${scoreDots(c.level)}</div>`).join('')}</div><p class="fineprint">${esc(cap.disclaimer)}</p></section></div>`}
