async function onboardingPage(){const src=await api('/data-sources');const configured=(src.data_sources||[]).filter(x=>x.configured);if(!state.market){return `${sectionHead('Onboarding','Generate a semantic workspace from real catalog metadata. No sample rows are read.')}<div class="source-grid">${(src.data_sources||[]).map(s=>`<div class="source-card"><div class="source-logo">${s.id.slice(0,2).toUpperCase()}</div><div><h3>${esc(s.label)}</h3><p>${esc(s.metadata||s.dialect)} · ${s.configured?'ready':'configure environment first'}</p></div>${pill(s.configured?'Configured':'Not configured',s.configured?'success':'neutral')}</div>`).join('')}</div><section class="card connect-form"><div class="card-head"><div><span class="eyebrow">CREATE WORKSPACE</span><h3>Discover metadata and generate semantics</h3></div>${pill('metadata only','success')}</div>${configured.length?`<div class="form-grid"><label>Data source<select id="connectSourceId">${configured.map(x=>`<option value="${esc(x.id)}">${esc(x.label)}</option>`).join('')}</select></label><label>Workspace ID<input id="connectWorkspaceId" placeholder="finance-prod"></label><label>Display name<input id="connectWorkspaceName" placeholder="Finance Analytics"></label><label>Database / schemas <small>(comma separated, optional)</small><input id="connectSchemas" placeholder="analytics, curated"></label></div><label class="check-row"><input type="checkbox" id="connectDiscover" checked> Discover relationship candidates after catalog sync</label><button id="connectSource" class="btn primary">Connect & generate workspace</button>`:`<div class="notice"><strong>No connector is configured yet.</strong><span>Open README.md and set the environment variables for Athena, PostgreSQL, Snowflake or Databricks, then restart the container.</span></div>`}</section>`}const d=await api(`/onboarding/status?market=${state.market}`);return `${sectionHead('Onboarding','Refresh metadata and review generated semantics. Sample rows remain disabled.',`<button id="discoverRels" class="btn secondary">Discover relationships</button><button id="resyncWorkspace" class="btn primary">Resync metadata</button>`)}<div class="quick-grid">${statCard('Tables',d.tables,'cataloged')}${statCard('Columns',d.columns,'metadata available')}${statCard('Descriptions',Math.round(d.description_coverage)+'%','metadata only')}${statCard('Workspace',state.market,'runtime generated')}</div><div class="card onboarding-flow"><div>Connected source</div><b>→</b><div>Metadata catalog</div><b>→</b><div>Generated semantic draft</div><b>→</b><div>Relationship review</div><b>→</b><div>Certify & publish</div></div>`}
async function actionsPage(){const d=await api(`/actions?market=${state.market}`);return `${sectionHead('Actions','Governed writeback. No arbitrary database writes.')}<div class="action-grid">${(d.actions||[]).map(a=>`<div class="action-card"><div><span class="eyebrow">ACTION</span><h3>${esc(a.label||a.id)}</h3><p>${esc(a.description||'')}</p></div>${pill(a.allowed?'Allowed':'Restricted',a.allowed?'success':'warn')}<button class="btn secondary" ${a.allowed?'':'disabled'}>Dry run</button></div>`).join('')||empty('No actions configured.')}</div>`}
