async function settingsPage(){const src=await api('/data-sources');const ready=await api('/ready');const sec=state.market?await api(`/security/me?market=${state.market}`):state.boot.security;const cap=state.market?await api(`/capabilities?market=${state.market}`):null;return `${sectionHead('Settings','Runtime, identity, connectors and deployment readiness.')}<div class="split"><section class="card"><div class="card-head"><h3>Runtime</h3>${pill(state.boot.app.environment==='production'?'PRODUCTION':state.boot.app.mode.toUpperCase(),state.boot.app.environment==='production'?'success':'info')}</div><div class="settings-list"><div><span>Version</span><strong>${esc(state.boot.app.version)}</strong></div><div><span>Workspace</span><strong>${esc(state.market||'Not created')}</strong></div><div><span>Role</span><strong>${esc(state.role)}</strong></div><div><span>Readiness</span><strong>${ready.ready?'Ready':'Needs configuration'}</strong></div></div></section><section class="card"><div class="card-head"><h3>Security context</h3></div><pre class="json-small">${esc(JSON.stringify(sec,null,2))}</pre></section></div><section class="card"><div class="card-head"><h3>Production readiness checks</h3>${pill(ready.ready?'Ready':'Review',ready.ready?'success':'warn')}</div><div class="settings-list">${(ready.checks||[]).map(x=>`<div><span>${esc(x.name.replaceAll('_',' '))}</span><strong>${x.ok?'✓':'!'} ${esc(x.detail)}</strong></div>`).join('')}</div></section>${cap?`<section class="card"><div class="card-head"><h3>Platform maturity definition</h3></div><p class="fineprint">${esc(cap.disclaimer)}</p></section>`:''}`}


function graphNodeTypeClass(t='node'){return 'type-'+String(t).replace(/[^a-z0-9_-]/gi,'-').toLowerCase()}
