function graphHash(text){let h=2166136261;for(let i=0;i<text.length;i++){h^=text.charCodeAt(i);h=Math.imul(h,16777619)}return h>>>0}
function drawSemanticGraph(data){const host=$('#graphCanvas');if(!host||!data)return;if(state.graphView?.raf)cancelAnimationFrame(state.graphView.raf);const raw=(data.nodes||[]).slice(0,500),ids=new Set(raw.map(n=>n.id)),edges=(data.edges||[]).filter(e=>ids.has(e.source_id)&&ids.has(e.target_id));if(!raw.length){host.innerHTML=empty('No graph nodes available.');return}host.innerHTML='<canvas id="semanticGraphCanvas" aria-label="Force-directed semantic knowledge graph"></canvas><div id="graphTip" class="graph-tip"></div>';const canvas=$('#semanticGraphCanvas'),ctx=canvas.getContext('2d'),tip=$('#graphTip');const degree={};edges.forEach(e=>{degree[e.source_id]=(degree[e.source_id]||0)+1;degree[e.target_id]=(degree[e.target_id]||0)+1});const nodes=raw.map((n,i)=>{const h=graphHash(n.id),a=(h%6283)/1000,r=80+(h%260);return {...n,x:Math.cos(a)*r,y:Math.sin(a)*r,vx:0,vy:0,r:Math.min(10,4.2+Math.sqrt(degree[n.id]||1)*1.2)}});const byId=Object.fromEntries(nodes.map(n=>[n.id,n]));const view={canvas,ctx,nodes,edges,byId,degree,scale:1,ox:0,oy:0,selected:state.graphSelected,hovered:null,drag:null,pan:null,frame:0,alpha:1,raf:null};state.graphView=view;function resize(){const dpr=Math.min(2,window.devicePixelRatio||1),rect=host.getBoundingClientRect();canvas.width=Math.max(1,Math.floor(rect.width*dpr));canvas.height=Math.max(1,Math.floor(rect.height*dpr));canvas.style.width=rect.width+'px';canvas.style.height=rect.height+'px';view.w=rect.width;view.h=rect.height;view.dpr=dpr;draw()}resize();if(window.ResizeObserver)new ResizeObserver(resize).observe(host);function screen(n){return {x:view.w/2+view.ox+n.x*view.scale,y:view.h/2+view.oy+n.y*view.scale}}function world(px,py){return {x:(px-view.w/2-view.ox)/view.scale,y:(py-view.h/2-view.oy)/view.scale}}function hit(px,py){let best=null,bd=18;for(const n of nodes){const p=screen(n),d=Math.hypot(px-p.x,py-p.y);if(d<Math.max(bd,n.r*view.scale+6)){best=n;bd=d}}return best}function connectedSet(id){const set=new Set([id]);edges.forEach(e=>{if(e.source_id===id)set.add(e.target_id);if(e.target_id===id)set.add(e.source_id)});return set}function draw(){const dpr=view.dpr||1;ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,view.w,view.h);ctx.fillStyle='#0b1020';ctx.fillRect(0,0,view.w,view.h);const focus=view.hovered?.id||view.selected,connected=focus?connectedSet(focus):null;ctx.lineCap='round';for(const e of edges){const a=byId[e.source_id],b=byId[e.target_id];if(!a||!b)continue;const pa=screen(a),pb=screen(b),active=focus&&(e.source_id===focus||e.target_id===focus);ctx.beginPath();ctx.moveTo(pa.x,pa.y);ctx.lineTo(pb.x,pb.y);ctx.strokeStyle=active?'rgba(148,197,255,.82)':e.trusted_for_queries?'rgba(94,234,212,.28)':'rgba(148,163,184,.13)';ctx.lineWidth=active?1.7:e.trusted_for_queries?1.15:.7;ctx.stroke()}const labels=new Set([...nodes].sort((a,b)=>(degree[b.id]||0)-(degree[a.id]||0)).slice(0,28).map(n=>n.id));for(const n of nodes){const p=screen(n),active=!focus||connected?.has(n.id),selected=n.id===view.selected,hover=n.id===view.hovered?.id;ctx.globalAlpha=active?1:.18;ctx.beginPath();ctx.arc(p.x,p.y,Math.max(3,n.r*view.scale),0,Math.PI*2);ctx.fillStyle=graphColor(n.node_type);ctx.shadowColor=selected||hover?graphColor(n.node_type):'transparent';ctx.shadowBlur=selected||hover?16:0;ctx.fill();ctx.shadowBlur=0;if(selected){ctx.strokeStyle='#fff';ctx.lineWidth=2;ctx.stroke()}if((labels.has(n.id)&&view.scale>.72)||selected||hover){ctx.font=`${selected||hover?'600':'500'} 11px Inter,system-ui,sans-serif`;ctx.fillStyle=selected||hover?'#f8fafc':'#cbd5e1';ctx.globalAlpha=active?1:.22;ctx.fillText(String(n.label||n.id).slice(0,34),p.x+Math.max(7,n.r*view.scale+5),p.y+4)}}ctx.globalAlpha=1}function physics(){if(view.alpha<.012&&!view.drag){draw();view.raf=null;return}const alpha=view.alpha;const cell=110,grid=new Map();for(const n of nodes){const k=`${Math.floor(n.x/cell)},${Math.floor(n.y/cell)}`;(grid.get(k)||grid.set(k,[]).get(k)).push(n)}for(const a of nodes){const gx=Math.floor(a.x/cell),gy=Math.floor(a.y/cell);for(let xx=gx-1;xx<=gx+1;xx++)for(let yy=gy-1;yy<=gy+1;yy++){for(const b of (grid.get(`${xx},${yy}`)||[])){if(a===b||a.id>b.id)continue;const dx=b.x-a.x,dy=b.y-a.y,d2=Math.max(80,dx*dx+dy*dy),d=Math.sqrt(d2),force=(900*alpha)/d2,fx=force*dx/d,fy=force*dy/d;a.vx-=fx;a.vy-=fy;b.vx+=fx;b.vy+=fy}}}for(const e of edges){const a=byId[e.source_id],b=byId[e.target_id];if(!a||!b)continue;const dx=b.x-a.x,dy=b.y-a.y,d=Math.max(1,Math.hypot(dx,dy)),target=e.trusted_for_queries?72:92,k=.018*alpha,force=(d-target)*k,fx=force*dx/d,fy=force*dy/d;a.vx+=fx;a.vy+=fy;b.vx-=fx;b.vy-=fy}for(const n of nodes){if(view.drag?.id===n.id){n.vx=n.vy=0;continue}n.vx+=(-n.x)*.0009*alpha;n.vy+=(-n.y)*.0009*alpha;n.vx*=.88;n.vy*=.88;n.x+=n.vx;n.y+=n.vy}view.alpha*=.985;view.frame++;draw();view.raf=requestAnimationFrame(physics)}function restart(a=.35){view.alpha=Math.max(view.alpha,a);if(!view.raf)view.raf=requestAnimationFrame(physics)}canvas.onwheel=e=>{e.preventDefault();const rect=canvas.getBoundingClientRect(),px=e.clientX-rect.left,py=e.clientY-rect.top,before=world(px,py),factor=e.deltaY<0?1.12:.89;view.scale=Math.max(.25,Math.min(4,view.scale*factor));const after=screen(before);view.ox+=px-after.x;view.oy+=py-after.y;draw()};canvas.onpointerdown=e=>{canvas.setPointerCapture(e.pointerId);const rect=canvas.getBoundingClientRect(),px=e.clientX-rect.left,py=e.clientY-rect.top,n=hit(px,py);if(n){view.drag={id:n.id};view.selected=n.id;state.graphSelected=n.id;selectGraphNode(n.id,data);const w=world(px,py);n.x=w.x;n.y=w.y;restart(.5)}else view.pan={x:px,y:py,ox:view.ox,oy:view.oy}};canvas.onpointermove=e=>{const rect=canvas.getBoundingClientRect(),px=e.clientX-rect.left,py=e.clientY-rect.top;if(view.drag){const n=byId[view.drag.id],w=world(px,py);n.x=w.x;n.y=w.y;n.vx=n.vy=0;restart(.35);return}if(view.pan){view.ox=view.pan.ox+(px-view.pan.x);view.oy=view.pan.oy+(py-view.pan.y);draw();return}const n=hit(px,py);view.hovered=n||null;canvas.style.cursor=n?'pointer':'grab';if(n){tip.style.display='block';tip.style.left=(px+14)+'px';tip.style.top=(py+14)+'px';tip.innerHTML=`<strong>${esc(n.label)}</strong><span>${esc(n.node_type)} · ${degree[n.id]||0} links</span>`}else tip.style.display='none';draw()};canvas.onpointerup=()=>{view.drag=null;view.pan=null;canvas.style.cursor='grab';restart(.2)};canvas.onpointerleave=()=>{view.hovered=null;tip.style.display='none';view.drag=null;view.pan=null;draw()};canvas.ondblclick=e=>{const rect=canvas.getBoundingClientRect(),n=hit(e.clientX-rect.left,e.clientY-rect.top);if(n)focusGraphNode(n.id)};view.draw=draw;view.restart=restart;const zin=$('#graphZoomIn'),zout=$('#graphZoomOut'),reset=$('#graphReset');if(zin)zin.onclick=()=>{view.scale=Math.min(4,view.scale*1.2);draw()};if(zout)zout.onclick=()=>{view.scale=Math.max(.25,view.scale/1.2);draw()};if(reset)reset.onclick=()=>{view.scale=1;view.ox=view.oy=0;view.selected=null;state.graphSelected=null;draw()};view.raf=requestAnimationFrame(physics)}
function selectGraphNode(id,data){state.graphSelected=id;const node=(data.nodes||[]).find(n=>n.id===id);if(!node)return;if(state.graphView){state.graphView.selected=id;state.graphView.alpha=Math.max(state.graphView.alpha,.08);state.graphView.draw?.()}const connected=(data.edges||[]).filter(e=>e.source_id===id||e.target_id===id);const a=node.attributes||{};$('#graphInspector').innerHTML=`<div class="graph-detail"><div class="graph-detail-top"><div>${pill(node.node_type||'node','info')}<h3>${esc(node.label)}</h3><p>${esc(node.summary||a.description||'No description available.')}</p></div><button id="focusGraphNode" class="btn secondary compact">Focus</button></div><div class="trust-meters"><div><span>Authority</span><strong>${Math.round((node.authority||0)*100)}%</strong><i><b style="width:${Math.round((node.authority||0)*100)}%"></b></i></div><div><span>Freshness</span><strong>${Math.round((node.freshness||0)*100)}%</strong><i><b style="width:${Math.round((node.freshness||0)*100)}%"></b></i></div></div><div class="detail-list"><div><span>Status</span><strong>${esc(node.status||'—')}</strong></div>${a.database?`<div><span>Database</span><strong>${esc(a.database)}</strong></div>`:''}${a.table?`<div><span>Table</span><strong>${esc(a.table)}</strong></div>`:''}${a.column?`<div><span>Column</span><strong>${esc(a.column)}</strong></div>`:''}</div><div class="divider"></div><span class="eyebrow">CONNECTED RELATIONSHIPS</span><div class="edge-mini">${connected.slice(0,24).map(e=>`<div><span>${esc(e.edge_type)}</span><small>${esc(e.source_id===id?e.target_id:e.source_id)}</small>${e.trusted_for_queries?pill('trusted','success'):''}</div>`).join('')||'<span class="muted">No visible relationships in this neighborhood.</span>'}</div></div>`;$('#focusGraphNode').onclick=()=>focusGraphNode(id);if(state.graphView)state.graphView.draw?.()}
