const p2ui={assetId:'',selectedRun:'',impactNode:''};
const p2path=(p,extra={})=>p+'?'+new URLSearchParams({workspace:state.market,...extra}).toString();
const p2post=(p,obj={})=>api(p2path(p),{method:'POST',body:JSON.stringify(obj)});
const p2assetName=(assets,id)=>{const a=assets.find(a=>a.asset_id===id);return a?`${a.source_id} · ${a.database}.${a.table}`:id};
const p2kindTone=s=>['complete','approved','certified','pass','accepted','reviewed','evidenced'].includes(s)?'success':['fail','rejected','error','needs_remediation','needs_review'].includes(s)?'warn':'neutral';
function p2assetSelect(assets,selected,id='p2-asset'){return `<select class="select p2-select" id="${id}">${assets.map(a=>`<option value="${esc(a.asset_id)}" ${selected===a.asset_id?'selected':''}>${esc(a.source_id)} · ${esc(a.database)}.${esc(a.table)}</option>`).join('')}</select>`}
function p2stats(d){return `<div class="summary-strip p2-stats"><div><span>Scoped assets</span><strong>${d.assets.length}</strong></div><div><span>Profiles recorded</span><strong>${d.profile_count}</strong></div><div><span>Contracts saved</span><strong>${d.contracts}</strong></div><div><span>Measured relationships</span><strong>${d.relationships}</strong></div></div>`}
function p2head(heading,desc,d,actions=''){return `${sectionHead(heading,desc,actions)}${p2stats(d)}<div class="p2-context"><span class="eyebrow">SCOPE-BOUND · ${esc(d.source_id.toUpperCase())}</span><span>${esc(d.scope_id)} · exact ${d.assets.length} selected tables</span><span>Aggregate evidence only — no record samples are saved</span></div>`}
async function phase2Page(){
 const d=await api(p2path('/phase2/overview'));
 if(!p2ui.assetId||!d.assets.some(a=>a.asset_id===p2ui.assetId))p2ui.assetId=d.assets[0]?.asset_id||'';
 if(!p2ui.assetId)return empty('Choose tables in Enterprise Catalog and generate a workspace first.');
 if(state.tab==='profile')return p2profilePage(d);
 if(state.tab==='contracts')return p2contractPage(d);
 if(state.tab==='evidence')return p2relationshipPage(d);
 if(state.tab==='quality')return p2qualityPage(d);
 return p2pipelinePage(d);
}
async function p2profilePage(d){
 const profiles=(await api(p2path('/phase2/profiles',{asset_id:p2ui.assetId}))).profiles;
 const meta=await api(p2path(`/phase2/assets/${encodeURIComponent(p2ui.assetId)}/metadata`));
 const p=profiles[0];
 return `${p2head('Data Profiling','Inspect metadata and run measured aggregate diagnostics for the exact selected source table.',d,
 `<div class="p2-top-actions">${p2assetSelect(d.assets,p2ui.assetId)}<select class="select" id="p2-tier"><option value="metadata">Metadata · no scan</option><option value="standard" selected>Standard · nulls & uniqueness</option><option value="deep">Deep · numeric distributions</option></select><button class="btn primary" id="p2-profile-run">Run profile</button></div>`)}
 ${p?`<section class="card p2-card"><div class="card-head"><div><span class="eyebrow">LATEST PROFILE · ${esc(p.tier)}</span><h3>${esc(p.profile_id)}</h3></div>${pill(p.status,p2kindTone(p.status))}</div>
 <div class="p2-kpis"><div><span>Rows measured</span><strong>${p.row_count===null?'Metadata':fmt(p.row_count)}</strong></div><div><span>Columns profiled</span><strong>${p.columns_profiled}/${p.columns_total}</strong></div><div><span>Queries executed</span><strong>${p.queries_executed}</strong></div><div><span>Schema drift</span><strong>${p.schema_drift_detected?'Detected':'No change detected'}</strong></div></div>
 ${simpleTable(['Column','Data type / role','Null %','Distinct count','Uniqueness','Evidence'],p.columns.map(c=>`<tr><td><strong>${esc(c.name)}</strong>${c.sensitive_candidate?pill('Sensitive candidate','warn'):''}</td><td>${esc(c.type)}<small class="sub">${esc(c.suggested_role)}</small></td><td>${c.measured?c.null_pct+'%':'—'}</td><td>${c.measured?fmt(c.distinct_count):'—'}</td><td>${c.measured?Math.round(100*c.uniqueness_ratio)+'%':'—'}</td><td>${c.numeric_summary?`<small>Min ${c.numeric_summary.min_value} · Avg ${c.numeric_summary.mean_value} · Max ${c.numeric_summary.max_value}</small>`:pill(c.measured?'measured':'metadata',c.measured?'success':'neutral')}</td></tr>`))}
 ${p.diagnostics.length?`<div class="notice warn">Some columns could not be measured: ${esc(JSON.stringify(p.diagnostics))}</div>`:''}</section>`:
 `<section class="card p2-card"><h3>No measured profile yet</h3><p>Start with metadata to inspect the source schema without scanning data, then choose Standard or Deep for aggregate evidence.</p>
 ${simpleTable(['Column','Type','Suggested role'],meta.columns.map(c=>`<tr><td>${esc(c.name)}</td><td>${esc(c.type)}</td><td>${esc(c.suggested_role)}</td></tr>`))}</section>`}
 <div class="fineprint">Deep profiling calculates numeric minima/maxima/averages where supported, excludes sensitive candidate fields from numeric summaries, and never stores individual records. Queries on cloud warehouses can incur scan charges.</div>`;
}
async function p2contractPage(d){
 const contracts=(await api(p2path('/phase2/contracts',{asset_id:p2ui.assetId}))).contracts;
 const c=contracts.find(x=>x.asset_id===p2ui.assetId);
 if(!c)return empty('No scoped contract available.');
 const roles=['identifier','foreign_key_candidate','temporal','measure','dimension','attribute','ignore'];
 return `${p2head('Dataset Contracts','Review column roles, owners and quality expectations before certifying a physical dataset.',d,p2assetSelect(d.assets,p2ui.assetId))}
 <section class="card p2-card"><div class="card-head"><div><span class="eyebrow">VERSION ${c.version} · ${esc(c.source)}</span><h3>${esc(p2assetName(d.assets,c.asset_id))}</h3></div>${pill(c.status,p2kindTone(c.status))}</div>
 <div class="p2-form-grid"><label>Data owner<input class="input" id="p2-owner" value="${esc(c.owner)}" placeholder="e.g. retail-data-steward"></label><label>Freshness SLA (hours)<input class="input" id="p2-sla" type="number" min="1" max="8760" value="${esc(c.freshness_sla_hours??'')}" placeholder="Optional"></label><label class="p2-wide">Dataset description<input class="input" id="p2-contract-desc" value="${esc(c.description)}" placeholder="Business purpose and usage constraints"></label></div>
 ${simpleTable(['Physical column','Type','Semantic role','Required','Sensitive','Description'],c.columns.map(x=>`<tr class="p2-contract-column" data-column="${esc(x.name)}"><td><strong>${esc(x.name)}</strong></td><td><code>${esc(x.physical_type)}</code></td><td><select class="select p2-role">${roles.map(k=>`<option value="${k}" ${k===x.role?'selected':''}>${k.replaceAll('_',' ')}</option>`).join('')}</select></td><td><input class="p2-required" type="checkbox" ${x.required?'checked':''}></td><td><input class="p2-sensitive" type="checkbox" ${x.sensitive?'checked':''} ${x.sensitive?'disabled title="Flag from physical metadata"':''}></td><td><input class="input p2-column-desc" value="${esc(x.description)}" placeholder="Column meaning"></td></tr>`))}
 <div class="p2-actions"><button id="p2-contract-save" class="btn primary">Save draft</button><input id="p2-contract-note" class="input" placeholder="Review note / certification rationale"><button class="btn secondary p2-contract-transition" data-transition="reviewed" ${c.status==='draft'?'':'disabled'}>Review</button><button class="btn secondary p2-contract-transition" data-transition="certified" ${c.status==='reviewed'?'':'disabled'}>Certify</button><button class="btn secondary p2-contract-transition" data-transition="draft" ${['reviewed','certified','rejected'].includes(c.status)?'':'disabled'}>Return to draft</button><button class="btn secondary p2-contract-transition" data-transition="rejected" ${['draft','reviewed'].includes(c.status)?'':'disabled'}>Reject</button></div>
 <p class="fineprint">Certification requires a responsible owner, a recent complete measured profile of the same schema, and a recorded review. Any edit returns the contract to draft.</p></section>`;
}
function p2erd(assets,relations){
 const chosen=assets.slice(0,12), count=chosen.length, ncols=Math.min(4,Math.max(1,Math.ceil(Math.sqrt(count))));
 const rows=Math.ceil(count/ncols), w=1000,h=Math.max(220,rows*145+30),pw=196,ph=78;
 const coords={};chosen.forEach((a,i)=>{const col=i%ncols,row=Math.floor(i/ncols);const x=25+col*((w-50-pw)/Math.max(1,ncols-1)),y=20+row*145;coords[a.asset_id]={x,y}});
 const lines=relations.filter(r=>coords[r.from_asset]&&coords[r.to_asset]).slice(0,40).map(r=>{const a=coords[r.from_asset],b=coords[r.to_asset],x1=a.x+pw/2,y1=a.y+ph/2,x2=b.x+pw/2,y2=b.y+ph/2;
 const verified=r.status==='approved',measured=!!r.evidence,color=verified?'#22866c':measured?'#e49a42':'#bac4d7';return `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${color}" stroke-width="${verified?3:2}" stroke-dasharray="${measured?'0':'5 7'}" opacity=".85" marker-end="url(#p2-er-arrow)"><title>${esc(p2assetName(assets,r.from_asset)+'.'+(r.from_columns||[r.from_column]).join(', ')+' → '+p2assetName(assets,r.to_asset)+'.'+(r.to_columns||[r.to_column]).join(', '))} — ${esc(r.status)}${r.evidence?' · coverage '+Math.round(r.evidence.coverage*100)+'%':''}</title></line>`}).join('');
 const boxes=chosen.map(a=>{const {x,y}=coords[a.asset_id];const involved=relations.filter(r=>r.from_asset===a.asset_id||r.to_asset===a.asset_id).length;
  return `<g><rect x="${x}" y="${y}" width="${pw}" height="${ph}" rx="12" fill="#ffffff" stroke="#d9e0ef" stroke-width="1.5"/><rect x="${x}" y="${y}" width="6" height="${ph}" rx="3" fill="#5c65b8"/><text x="${x+18}" y="${y+29}" font-size="17" fill="#1e2b47" font-weight="700">${esc(a.table)}</text><text x="${x+18}" y="${y+50}" font-size="12" fill="#7a849b">${esc(a.database)}</text><text x="${x+18}" y="${y+65}" font-size="10" fill="#7a849b">${involved} relationship(s)</text></g>`}).join('');
 return `<section class="card p2-card"><div class="card-head"><h3>Evidence-aware entity diagram</h3>${pill(chosen.length+' datasets · '+relations.length+' candidates')}</div><div class="p2-er-scroll"><svg class="p2-er" viewBox="0 0 ${w} ${h}" role="img" aria-label="Scoped source tables and relationship evidence"><defs><marker id="p2-er-arrow" markerWidth="7" markerHeight="7" refX="6" refY="3" orient="auto"><path d="M0 0 L6 3 L0 6" fill="none" stroke="#99a4b8" stroke-width="1.2"/></marker></defs>${lines}${boxes}</svg></div><div class="p2-er-legend"><span><i class="p2-er-green"></i>Approved after measurement</span><span><i class="p2-er-gold"></i>Measured, awaiting decision</span><span><i class="p2-er-grey"></i>Naming candidate only</span></div>${assets.length>12?`<p class="fineprint">Showing first 12 scoped assets. Use the table for all candidates.</p>`:''}</section>`;
}
