async function p2qualityPage(d){
 const [rr,run]=await Promise.all([api(p2path('/phase2/quality/rules')),api(p2path('/phase2/quality/runs'))]);
 const rules=rr.rules, runs=run.runs,last=runs.find(x=>x.run_id===p2ui.selectedRun)||runs[0];
 const meta=await api(p2path(`/phase2/assets/${encodeURIComponent(p2ui.assetId)}/metadata`));
 const types=[['row_count_min','Minimum row count'],['not_null','Column must be non-null'],['completeness_min','Minimum completeness ratio'],['unique_min','Minimum uniqueness ratio'],['relationship_coverage_min','Minimum FK coverage']];
 const rels=(await api(p2path('/phase2/relationships'))).relationships.filter(x=>x.from_asset===p2ui.assetId);
 return `${p2head('Quality Center','Set expectations, measure quality, issue steward rulings, and track remediation.',d,`<button class="btn primary" id="p2-quality-run" ${rules.length?'':'disabled'}>Run ${rules.length} active rules</button>`)}
 <section class="card p2-card"><div class="card-head"><h3>Create quality rule</h3>${pill(rules.length+' active rules')}</div><div class="p2-form-grid"><label>Dataset${p2assetSelect(d.assets,p2ui.assetId)}</label><label>Check<select class="select" id="p2-rule-type">${types.map(([v,l])=>`<option value="${v}">${l}</option>`).join('')}</select></label><label>Column<select class="select" id="p2-rule-column">${meta.columns.map(c=>`<option value="${esc(c.name)}">${esc(c.name)}</option>`).join('')}</select></label><label>Threshold (ratio 0–1, except row count)<input class="input" id="p2-rule-threshold" type="number" min="0" step="0.01" value="1"></label><label>Relationship<select class="select" id="p2-rule-relationship">${rels.map(r=>`<option value="${esc(r.relationship_id)}">${esc(r.from_column)} → ${esc(p2assetName(d.assets,r.to_asset))}</option>`).join('')}</select></label><label>Description<input class="input" id="p2-rule-desc" placeholder="Why this check matters"></label></div><button class="btn secondary" id="p2-rule-create">Create rule</button>
 ${simpleTable(['Dataset','Rule','Threshold','Column','Status'],rules.map(r=>`<tr><td>${esc(p2assetName(d.assets,r.asset_id))}</td><td>${esc(r.rule_type.replaceAll('_',' '))}</td><td>${r.threshold}</td><td>${esc(r.column||'—')}</td><td><button class="btn secondary compact p2-rule-toggle" data-rule="${esc(r.rule_id)}" data-next="${r.status==='active'?'disabled':'active'}">${r.status==='active'?'Disable':'Enable'}</button></td></tr>`))}</section>
 <section class="card p2-card"><div class="card-head"><h3>Quality observations</h3>${last?pill(last.review_status,p2kindTone(last.review_status)):pill('Not run')}</div>
 ${last?`<div class="p2-kpis"><div><span>Passed</span><strong>${last.passed}</strong></div><div><span>Failed</span><strong>${last.failed}</strong></div><div><span>Errors</span><strong>${last.errors}</strong></div><div><span>Remediation</span><strong>${esc(last.remediation_status)}</strong></div></div>
 ${simpleTable(['Rule','Observed','Expected','Result','Evidence'],last.observations.map(o=>`<tr><td>${esc(o.rule_type)} <small class="sub">${esc(o.column||p2assetName(d.assets,o.asset_id))}</small></td><td>${o.actual==null?'—':o.actual}</td><td>${o.threshold}</td><td>${pill(o.status,p2kindTone(o.status))}${o.error?`<small class="sub">${esc(o.error)}</small>`:''}</td><td><small>${esc(o.evidence_id||'none')}</small></td></tr>`))}
 <div class="p2-form-grid"><label>Ruling<select class="select" id="p2-quality-decision"><option value="accepted">Accept (only clean runs)</option><option value="needs_remediation">Needs remediation</option><option value="waived">Waiver with rationale</option></select></label><label>Remediation<select class="select" id="p2-quality-remed-status"><option value="open">Open</option><option value="in_progress">In progress</option><option value="resolved">Resolved (requires ruling)</option></select></label><label>Owner<input class="input" id="p2-quality-owner" placeholder="Assigned steward"></label><label class="p2-wide">Evidence decision note<input id="p2-quality-note" class="input" placeholder="Required reason, ticket ID or incident"></label></div>
 <div class="p2-actions"><button class="btn secondary" id="p2-quality-review" data-run="${esc(last.run_id)}">Record ruling</button><button class="btn secondary" id="p2-quality-remediate" data-run="${esc(last.run_id)}">Update remediation</button></div>`:empty('Create at least one quality rule and run the engine to see evidence and review actions.')}</section>`;
}
async function p2pipelinePage(d){
 const [graph,tr]=await Promise.all([api(p2path('/phase2/lineage')),api(p2path('/phase2/transformations'))]);
 const kinds=['source','dataset','profile','transformation','lookup','relationship','contract'];
 const nodesByKind=Object.fromEntries(kinds.map(k=>[k,graph.nodes.filter(n=>n.kind===k)]));
 return `${p2head('Lineage Studio','Visual trace from physical sources through profiles, contracts, declared transformations and validated lookup evidence.',d)}
 <section class="card p2-card"><div class="card-head"><h3>Evidence lineage map</h3>${pill(graph.nodes.length+' nodes · '+graph.edges.length+' edges')}</div>
 <div class="p2-lineage-canvas">${kinds.map((k,i)=>`<div class="p2-lineage-stage"><div class="p2-lineage-label"><span>${esc(k.toUpperCase())}</span><b>${nodesByKind[k].length}</b></div>${nodesByKind[k].slice(0,9).map(n=>`<button class="p2-lineage-node ${n.id===p2ui.impactNode?'selected':''}" data-node="${esc(n.id)}"><strong>${esc(n.label)}</strong><small>${esc(n.status)}</small></button>`).join('')||'<small class="p2-lineage-empty">Not yet recorded</small>'}${nodesByKind[k].length>9?`<small>+${nodesByKind[k].length-9} additional nodes</small>`:''}</div>`).join('')}</div>
 ${p2ui.impactNode?`<div class="p2-impact" id="p2-impact-result">Select another node to inspect impact, or use the edges below.</div>`:''}
 <details><summary>View ${graph.edges.length} directed evidence edges</summary>${simpleTable(['From','Relationship','To','Evidence'],graph.edges.slice(0,180).map(e=>`<tr><td><small>${esc(e.source_id)}</small></td><td>${esc(e.kind)}</td><td><small>${esc(e.target_id)}</small></td><td>${pill(e.evidence)}</td></tr>`))}</details>
 </section><section class="card p2-card"><div class="card-head"><h3>Declare a transformation</h3>${pill(tr.transformations.length+' documented')}</div><p class="muted">Register actual input/output assets only. A declaration is not proof of execution; it remains labeled as steward-declared until separately verified.</p>
 <div class="p2-form-grid"><label>Transformation name<input class="input" id="p2-transform-label" placeholder="e.g. enrich order lines"></label><label>Input dataset${p2assetSelect(d.assets,d.assets[0].asset_id,'p2-transform-input')}</label><label>Output dataset${p2assetSelect(d.assets,d.assets.at(-1).asset_id,'p2-transform-output')}</label><label>Description<input class="input" id="p2-transform-desc" placeholder="Transformation provenance / job ID"></label></div><button id="p2-transform-add" class="btn secondary">Register lineage</button>
 ${simpleTable(['Transformation','Inputs','Outputs','Status'],tr.transformations.map(t=>`<tr><td><strong>${esc(t.label)}</strong></td><td>${t.inputs.map(i=>esc(p2assetName(d.assets,i))).join(', ')}</td><td>${t.outputs.map(i=>esc(p2assetName(d.assets,i))).join(', ')}</td><td>${pill(t.status)}</td></tr>`))}</section>`;
}
function bindPhase2(){
 const selected=$('#p2-asset');if(selected)selected.onchange=e=>{p2ui.assetId=e.target.value;renderPage()};
 const act=async(fn)=>{try{await fn();toast('Evidence updated','good');renderPage()}catch(e){toast(e.message,'bad')}};
 if($('#p2-profile-run'))$('#p2-profile-run').onclick=()=>act(()=>p2post('/phase2/profiles',{asset_id:p2ui.assetId,tier:$('#p2-tier').value,max_columns:200}));
 if($('#p2-contract-save')){
  const c=()=>{const columns=$$('.p2-contract-column').map(el=>({name:el.dataset.column,role:el.querySelector('.p2-role').value,required:el.querySelector('.p2-required').checked,sensitive:el.querySelector('.p2-sensitive').checked,description:el.querySelector('.p2-column-desc').value}));return {owner:$('#p2-owner').value,description:$('#p2-contract-desc').value,freshness_sla_hours:$('#p2-sla').value?Number($('#p2-sla').value):null,columns}};
  $('#p2-contract-save').onclick=()=>act(()=>p2post(`/phase2/contracts/${encodeURIComponent(p2ui.assetId)}`,c()));
  $$('.p2-contract-transition').forEach(b=>b.onclick=()=>act(()=>p2post(`/phase2/contracts/${encodeURIComponent(p2ui.assetId)}/review`,{decision:b.dataset.transition,note:$('#p2-contract-note').value})));
 }
 if($('#p2-rel-create'))$('#p2-rel-create').onclick=()=>act(()=>p2post('/phase2/relationships',{from_asset:$('#p2-rel-source').value,to_asset:$('#p2-rel-target').value,from_columns:$('#p2-rel-source-keys').value.split(',').map(x=>x.trim()).filter(Boolean),to_columns:$('#p2-rel-target-keys').value.split(',').map(x=>x.trim()).filter(Boolean),role:$('#p2-rel-role').value}));
 if($('#p2-rel-refresh'))$('#p2-rel-refresh').onclick=()=>renderPage();
 $$('.p2-rel-validate').forEach(b=>b.onclick=()=>act(()=>p2post(`/phase2/relationships/${encodeURIComponent(b.dataset.rel)}/validate`)));
 $$('.p2-rel-approve,.p2-rel-reject').forEach(b=>b.onclick=()=>{const note=prompt('Record a review rationale (required):');if(note)act(()=>p2post(`/phase2/relationships/${encodeURIComponent(b.dataset.rel)}/review`,{decision:b.classList.contains('p2-rel-approve')?'approved':'rejected',note}))});
 if($('#p2-rule-create'))$('#p2-rule-create').onclick=()=>act(()=>p2post('/phase2/quality/rules',{asset_id:p2ui.assetId,rule_type:$('#p2-rule-type').value,column:$('#p2-rule-column').value,threshold:Number($('#p2-rule-threshold').value),relationship_id:$('#p2-rule-relationship').value||null,description:$('#p2-rule-desc').value}));
 $$('.p2-rule-toggle').forEach(b=>b.onclick=()=>{const note=prompt('Reason for changing quality rule status:');if(note)act(()=>p2post(`/phase2/quality/rules/${encodeURIComponent(b.dataset.rule)}/status`,{decision:b.dataset.next,note}))});
 if($('#p2-quality-run'))$('#p2-quality-run').onclick=()=>act(async()=>{const r=await p2post('/phase2/quality/run');p2ui.selectedRun=r.run_id});
 if($('#p2-quality-review'))$('#p2-quality-review').onclick=()=>act(()=>p2post(`/phase2/quality/runs/${encodeURIComponent($('#p2-quality-review').dataset.run)}/review`,{decision:$('#p2-quality-decision').value,note:$('#p2-quality-note').value}));
 if($('#p2-quality-remediate'))$('#p2-quality-remediate').onclick=()=>act(()=>p2post(`/phase2/quality/runs/${encodeURIComponent($('#p2-quality-remediate').dataset.run)}/remediate`,{status:$('#p2-quality-remed-status').value,note:$('#p2-quality-note').value,owner:$('#p2-quality-owner').value}));
 if($('#p2-transform-add'))$('#p2-transform-add').onclick=()=>act(()=>p2post('/phase2/transformations',{label:$('#p2-transform-label').value,inputs:[$('#p2-transform-input').value],outputs:[$('#p2-transform-output').value],description:$('#p2-transform-desc').value}));
 $$('.p2-lineage-node').forEach(b=>b.onclick=async()=>{p2ui.impactNode=b.dataset.node;$$('.p2-lineage-node').forEach(x=>x.classList.toggle('selected',x===b));let dest=$('#p2-impact-result');if(!dest){dest=document.createElement('div');dest.className='p2-impact';b.closest('.p2-card').append(dest)}dest.textContent='Looking up graph impact…';try{const d=await api(p2path('/phase2/lineage/impact',{node_id:p2ui.impactNode,depth:3}));dest.innerHTML=`<strong>Impact of ${esc(b.textContent.trim())}</strong><p>${d.nodes.length} connected nodes · ${d.edges.length} evidence edges</p><div>${d.nodes.filter(x=>x.id!==p2ui.impactNode).slice(0,20).map(n=>pill(n.label)).join(' ')}</div>`}catch(e){dest.textContent=e.message}});
}

