const p3ui={kind:'',selected:'',mode:'conceptual',focus:'',asset:'',actor:localStorage.getItem('dip-p3-actor')||'local-ui'};
const p3path=(path,query={})=>path+'?'+new URLSearchParams({workspace:state.market,...query}).toString();
const p3call=(path,method='GET',obj=null)=>api(p3path(path),{method,headers:{'X-User':p3ui.actor},...(obj!==null?{body:JSON.stringify(obj)}:{})});
const p3kinds=['entity','event','measure','code_set','business_concept','rule'];
function p3banner(over){return `<div class="summary-strip p2-stats"><div><span>Ontology objects</span><strong>${over.objects}</strong></div><div><span>Certified</span><strong>${over.by_status.certified||0}</strong></div><div><span>Blocked diagnostics</span><strong>${over.blocked}</strong></div><div><span>Provenance snapshots</span><strong>${over.evidence_records}</strong></div></div><div class="p3-caution"><strong>Review workspace, not production execution.</strong> Suggestions and SME rulings never enable a query join. Only certified objects qualify for a versioned ontology snapshot; Governed Ask connects certified semantic snapshots to supported execution.</div>`}
function p3head(title,subtitle,over,extra=''){return sectionHead(title,subtitle,extra)+p3banner(over)}
function p3actor(){return `<div class="p3-identity"><label>Local development reviewer identity <input class="input" id="p3-actor" value="${esc(p3ui.actor)}" maxlength="100" placeholder="local-ui"></label><small>Simulated X-User in dev mode only. Production uses verified ALB/OIDC identity; self-certification is blocked.</small></div>`}
async function phase3Page(){
 const [overview,olist]=await Promise.all([p3call('/phase3/overview'),p3call('/phase3/objects')]);
 const objects=olist.objects||[];
 if(!p3ui.selected||!objects.find(x=>x.object_id===p3ui.selected))p3ui.selected=objects[0]?.object_id||'';
 if(['ontology','studio'].includes(state.tab))return p3objectsPage(overview,objects);
 if(state.tab==='trust')return p3trustPage(overview,objects);
 if(state.tab==='questions')return p3questionsPage(overview,objects);
 return p3graphPage(overview,objects);
}
