function p3svg(graph){
 const nodes=graph.nodes.slice(0,120);const cols=Math.max(1,Math.min(6,Math.ceil(Math.sqrt(nodes.length*1.3))));
 const rows=Math.ceil(nodes.length/cols),w=1100,h=Math.max(390,rows*120+70);const c={};
 nodes.forEach((n,i)=>{c[n.id]={x:100+(i%cols)*(900/Math.max(1,cols-1)),y:70+Math.floor(i/cols)*120}});
 const edgeLines=(graph.edges||[]).filter(e=>c[e.source_id]&&c[e.target_id]).slice(0,450).map(e=>`<line x1="${c[e.source_id].x}" y1="${c[e.source_id].y}" x2="${c[e.target_id].x}" y2="${c[e.target_id].y}" stroke="#a7b7cc" stroke-width="1.5" opacity=".65"><title>${esc(e.kind)}</title></line>`).join('');
 const shapes=nodes.map(n=>{const p=c[n.id],color=n.status==='certified'?'#12a586':n.status==='reviewed'?'#deb34b':n.kind==='dataset'?'#6373b9':'#667da1';return `<g class="p3-graph-node" data-node="${esc(n.id)}" tabindex="0" role="button" aria-label="Inspect ${esc(n.label)}"><circle cx="${p.x}" cy="${p.y}" r="25" fill="${color}" stroke="white" stroke-width="3"/><text x="${p.x}" y="${p.y+5}" text-anchor="middle" fill="white" font-size="16">${n.kind==='measure'?'Σ':n.kind==='event'?'◷':n.kind==='code_set'?'#':n.kind==='rule'?'✓':'◇'}</text><text x="${p.x}" y="${p.y+43}" text-anchor="middle" font-size="12" fill="#1f3655" font-weight="650">${esc(n.label.slice(0,23))}</text><text x="${p.x}" y="${p.y+57}" text-anchor="middle" font-size="10" fill="#71829c">${esc(n.kind.replaceAll('_',' '))}</text><title>${esc(n.label)} · ${esc(n.status)}</title></g>`}).join('');
 return `<div class="p3-graph-wrap"><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Ontology ${esc(graph.mode)} graph with ${nodes.length} visible nodes"><defs><pattern id="p3grid" width="24" height="24" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".6" fill="#cbd5e1"/></pattern></defs><rect width="${w}" height="${h}" fill="url(#p3grid)"/>${edgeLines}${shapes}</svg></div>`;
}
