function p4status(overview){return `<div class="summary-strip p2-stats"><div><span>Release</span><strong>${esc(overview.active_release||'Not selected')}</strong></div><div><span>Certified usable</span><strong>${overview.eligible||0}</strong></div><div><span>Blocked</span><strong>${(overview.blocked||[]).length}</strong></div><div><span>Governance</span><strong>Fail-closed</strong></div></div>`}
function p4context(releases){return `<div class="p4-context"><label>Active pinned release <select id="p4-release" class="select"><option value="">Select release</option>${releases.map(x=>`<option value="${esc(x.release_id)}" ${p4ui.release===x.release_id?'selected':''}>${esc(x.release_id)} · ${esc(x.published_at.slice(0,10))}</option>`).join('')}</select></label><label>Development reviewer identity <input class="input" id="p4-actor" value="${esc(p4ui.actor)}" maxlength="100"></label></div>`}
async function phase4Page(){
 const [all,p3releases]=await Promise.all([p4get('releases'),p3call('/phase3/releases')]);const releases=all.releases||[];
 if(!releases.some(x=>x.release_id===p4ui.release))p4ui.release=releases[0]?.release_id||'';
 const overview=await p4get('overview',p4ui.release?{release_id:p4ui.release}:{});
 const header=sectionHead({'governed-ask':'Governed Ask + BI','plan-lab':'Semantic Plan Lab','golden':'Business-result benchmarks','ontology-releases':'Ontology Release Manager','impact-agent':'Impact & Agent Tools'}[state.tab],
   'Ontology-backed, evidence-cited, release-pinned query planning. Ask, reports and plan previews use the same certified metric compiler and AI review.')+p4status(overview)+p4context(releases);
 if(!releases.length && state.tab!=='ontology-releases')return header+`<div class="notice">No governed release yet. Independently certify an ontology object, publish a review-only snapshot, then open Ontology Releases to promote it.</div><button class="btn secondary" id="p4-open-releases">Open Ontology Releases</button>`;
 if(state.tab==='ontology-releases')return header+await p4releasePage(releases,p3releases.releases||[]);
 if(state.tab==='golden')return header+await businessBenchmarkPage();
 if(state.tab==='impact-agent')return header+await p4impactPage();
 return header+await p4askPage(state.tab==='plan-lab');
}
