function p4resultHtml(result){
 const p=result.plan||((result.sql&&result.object_id)?result:null);
 if(result.hits){return `<section class="card p2-card"><div class="card-head"><h3>Hierarchical GraphRAG · provenance-backed evidence</h3>${pill(result.hits.length+' matches')}</div>
 ${result.domains.map(d=>`<div class="p4-domain"><div class="p4-domain-head">⌁ ${esc(d.name)} ${pill(d.objects.length+' certified')}</div>${d.objects.map(o=>`<div class="p4-proof"><b>${esc(o.label)}</b>${pill(o.kind)}<small>Matched: ${esc(o.matched_terms.join(', '))} · ontology ${esc(o.object_id)}</small><code>Evidence ${esc((o.evidence_digest||'').slice(0,20))}…</code></div>`).join('')}</div>`).join('')||empty('No trusted evidence matched; nothing inferred.')}
 <p class="fineprint">The retrieval uses deterministic lexical ranking over certified ontology labels and measured provenance. No LLM inference is involved.</p><details><summary>Inspect exact retrieval payload</summary><pre class="json-small">${esc(JSON.stringify(result,null,2))}</pre></details></section>`}
 if(!p)return `<section class="card p2-card"><pre class="json-small">${esc(JSON.stringify(result,null,2))}</pre></section>`;
 if(result.status==='needs_clarification')return `<section class="card"><h3>Clarification needed</h3><p>${esc(result.clarification||result.answer)}</p></section>`;
 const rows=result.rows||result.result?.rows||[];
 return `<section class="card"><h3>${result.executed?'Verified business result':'Verified SQL preview'}</h3><p>${esc(result.answer||'')}</p>
 <p>Certified metrics: ${esc((p.metric_ids||[]).join(', '))}</p>${rows.length?simpleTable(Object.keys(rows[0]),rows.map(r=>`<tr>${Object.values(r).map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`)):''}
 <details><summary>SQL and evidence</summary><pre>${esc(p.sql)}</pre><pre>${esc(JSON.stringify(result.evidence||p.policy,null,2))}</pre></details></section>`;
}
