function buildBusinessDefinition(kind,binding){
 const grain=$('#p3-grain').value.split(',').map(x=>x.trim()).filter(Boolean);
 const formula=$('#p3-formula').value.trim(),condition=$('#p3-condition').value.trim(),sem={};
 if(grain.length)sem.grain=grain;
 if(kind==='measure'){
  const agg=$('#p3-aggregation').value;sem.aggregation=agg;sem.unit=$('#p3-unit').value.trim();
  sem.additivity=['avg','ratio','count_distinct'].includes(agg)?'non_additive':'additive';
  if(agg==='ratio'){
   const parts=formula.split('/').map(x=>x.trim());if(parts.length!==2)throw new Error('Enter numerator / denominator columns');
   sem.numerator={aggregation:'sum',expression:{column:parts[0]}};sem.denominator={aggregation:'sum',expression:{column:parts[1]}};
  }else if(agg!=='count'){
   const m=formula.match(/^([A-Za-z_][A-Za-z0-9_]*)\s*([+*\/-])\s*([A-Za-z_][A-Za-z0-9_]*)$/);
   if(m)sem.expression={op:{'+':'add','-':'subtract','*':'multiply','/':'divide'}[m[2]],args:[{column:m[1]},{column:m[3]}]};
   else{if(!/^[A-Za-z_][A-Za-z0-9_]*$/.test(formula))throw new Error('Use a bound column or two columns with an arithmetic operator');sem.expression={column:formula}}
  }
 }
 if(condition){const parts=condition.split('=');if(parts.length!==2)throw new Error('Enter a column=value condition');sem.filters=[{column:parts[0].trim(),op:'eq',value:(/^-?\d+(\.\d+)?$/.test(parts[1].trim())?Number(parts[1].trim()):parts[1].trim())}]}
 if($('#p3-time').value.trim())sem.time={column:$('#p3-time').value.trim(),timezone:'UTC',calendar:'gregorian'};
 return sem;
}
